insert into questions (id, exam, topic_id, status, difficulty, stem, lead_in, tags) values
('f3000000-0000-0000-0000-000000000001', 'mrcp1', '8804e531-a0b3-4614-9881-6656f0622d76',
insert into question_options (question_id, label, option_text, is_correct, rationale, sort_order) values
('f3000000-0000-0000-0000-000000000001', 'A', 'Anaemia of chronic disease', false, 'Ruled out because anaemia of chronic disease typically shows normal or raised ferritin (as an acute phase reactant) rather than the low ferritin seen here, which specifically indicates true iron deficiency.', 1),
('f3000000-0000-0000-0000-000000000001', 'B', 'Thalassaemia trait', false, 'Ruled out because thalassaemia trait typically causes a microcytic anaemia with normal or raised ferritin and a disproportionately low MCV relative to the degree of anaemia, and would not be explained by menorrhagia; iron studies here point to true deficiency instead.', 2),
('f3000000-0000-0000-0000-000000000001', 'C', 'Sideroblastic anaemia', false, 'Ruled out because sideroblastic anaemia typically shows a raised (not low) ferritin with ringed sideroblasts on bone marrow examination, unlike the iron-deficient picture described here.', 3),
('f3000000-0000-0000-0000-000000000001', 'D', 'Iron deficiency anaemia', true, 'Correct. A microcytic, hypochromic anaemia with a low ferritin (the most specific marker of reduced iron stores) in a woman with a clear source of chronic blood loss (heavy menstrual periods) is characteristic of iron deficiency anaemia.', 4),
('f3000000-0000-0000-0000-000000000001', 'E', 'Vitamin B12 deficiency', false, 'Ruled out because B12 deficiency causes a macrocytic (not microcytic) anaemia, the opposite red cell size pattern to that described here.', 5),
('f3000000-0000-0000-0000-000000000002', 'A', 'Reassurance with oral iron replacement alone, no further investigation', false, 'Ruled out because iron deficiency anaemia in a man without an obvious source requires investigation to exclude an underlying cause, particularly GI malignancy, rather than treating the anaemia alone without further workup.', 1),
('f3000000-0000-0000-0000-000000000002', 'B', 'Bone marrow biopsy as the first-line investigation', false, 'Ruled out because bone marrow biopsy is not the standard first-line investigation for unexplained iron deficiency anaemia; the priority is investigating for a source of blood loss, particularly in the GI tract.', 2),
('f3000000-0000-0000-0000-000000000002', 'C', 'Renal ultrasound as the first-line investigation', false, 'Ruled out because renal pathology is not the classic cause of iron deficiency anaemia in this context; GI sources (particularly malignancy) are the priority to exclude.', 3),
('f3000000-0000-0000-0000-000000000002', 'D', 'Repeat full blood count in 6 months with no other action', false, 'Ruled out because delaying investigation in unexplained iron deficiency anaemia in an at-risk group risks missing a treatable, potentially serious underlying cause such as colorectal cancer.', 4),
('f3000000-0000-0000-0000-000000000002', 'E', 'Upper and lower gastrointestinal endoscopy', true, 'Correct. In an adult man (or postmenopausal woman) with iron deficiency anaemia and no obvious source of blood loss, occult gastrointestinal malignancy or other GI pathology must be excluded; bidirectional endoscopy (upper GI endoscopy and colonoscopy) is the standard next investigation.', 5),
('f3000000-0000-0000-0000-000000000003', 'A', 'Folate deficiency', false, 'Ruled out because although folate deficiency also causes macrocytic anaemia with hypersegmented neutrophils, it does not typically cause neurological symptoms (peripheral neuropathy), and the specifically low B12 level here confirms B12, not folate, deficiency.', 1),
('f3000000-0000-0000-0000-000000000003', 'B', 'Hypothyroidism', false, 'Ruled out because although hypothyroidism can cause mild macrocytosis, it would not explain the hypersegmented neutrophils or peripheral neuropathy, and the specific low B12 level points to B12 deficiency.', 2),
('f3000000-0000-0000-0000-000000000003', 'C', 'Vitamin B12 deficiency', true, 'Correct. Macrocytic anaemia with hypersegmented neutrophils on blood film, peripheral neuropathy (paraesthesia), and a low serum B12 level in a vegan (a diet lacking animal-derived B12 sources) is characteristic of vitamin B12 deficiency.', 3),
('f3000000-0000-0000-0000-000000000003', 'D', 'Alcohol excess', false, 'Ruled out because although alcohol can cause macrocytosis, there is no history given, and the specific findings (hypersegmented neutrophils, low B12, dietary history) point to B12 deficiency.', 4),
('f3000000-0000-0000-0000-000000000003', 'E', 'Myelodysplastic syndrome', false, 'Ruled out because although MDS can cause macrocytic anaemia, the clear dietary risk factor and confirmed low B12 level make straightforward B12 deficiency the more likely diagnosis here.', 5),
('f3000000-0000-0000-0000-000000000004', 'A', 'Dietary B12 deficiency', false, 'Ruled out because dietary deficiency reflects inadequate intake, not the autoimmune process (positive intrinsic factor antibodies, atrophic gastritis) described here, which specifically indicates pernicious anaemia.', 1),
('f3000000-0000-0000-0000-000000000004', 'B', 'Pernicious anaemia', true, 'Correct. B12 deficiency caused by autoimmune destruction of gastric parietal cells (causing atrophic gastritis) and/or antibodies against intrinsic factor, impairing B12 absorption in the terminal ileum, defines pernicious anaemia, an autoimmune cause of B12 deficiency requiring lifelong B12 replacement, typically by injection.', 2),
('f3000000-0000-0000-0000-000000000004', 'C', 'Coeliac disease', false, 'Ruled out because although coeliac disease can cause malabsorption of various nutrients, the specific findings of intrinsic factor antibodies and atrophic gastritis point to pernicious anaemia, not coeliac disease.', 3),
('f3000000-0000-0000-0000-000000000004', 'D', $x$Crohn's disease affecting the terminal ileum$x$, false, $x$Ruled out because although terminal ileal Crohn's disease can impair B12 absorption, the specific autoimmune markers described (intrinsic factor antibodies, atrophic gastritis) point to pernicious anaemia rather than Crohn's disease.$x$, 4),
('f3000000-0000-0000-0000-000000000004', 'E', 'Chronic pancreatitis', false, 'Ruled out because although severe exocrine pancreatic insufficiency can rarely contribute to B12 malabsorption, the specific autoimmune findings described are classic and diagnostic for pernicious anaemia.', 5),
('f3000000-0000-0000-0000-000000000005', 'A', 'Beta-thalassaemia trait', true, 'Correct. A longstanding, mild microcytic anaemia with disproportionately low MCV relative to the degree of anaemia, normal ferritin (excluding iron deficiency), and a raised HbA2 on electrophoresis, in a patient of Mediterranean descent, is characteristic of beta-thalassaemia trait, a carrier state requiring no specific treatment beyond genetic counselling.', 1),
('f3000000-0000-0000-0000-000000000005', 'B', 'Iron deficiency anaemia', false, 'Ruled out because iron deficiency causes a low (not normal) ferritin; the normal ferritin here excludes iron deficiency as the cause of the microcytosis.', 2),
('f3000000-0000-0000-0000-000000000005', 'C', 'Alpha-thalassaemia trait', false, 'Ruled out because alpha-thalassaemia trait typically shows a normal HbA2 level (since alpha-globin chain reduction affects all haemoglobin types proportionally), unlike the raised HbA2 specifically seen in beta-thalassaemia trait.', 3),
('f3000000-0000-0000-0000-000000000005', 'D', 'Sideroblastic anaemia', false, 'Ruled out because sideroblastic anaemia typically shows a raised ferritin (iron overload) with ringed sideroblasts on bone marrow, not the normal ferritin and raised HbA2 pattern described here.', 4),
('f3000000-0000-0000-0000-000000000005', 'E', 'Anaemia of chronic disease', false, 'Ruled out because there is no chronic inflammatory or infective condition described, and the specific ethnic background with raised HbA2 points to beta-thalassaemia trait.', 5),
('f3000000-0000-0000-0000-000000000006', 'A', 'Hereditary spherocytosis', false, 'Ruled out because hereditary spherocytosis causes chronic haemolysis with spherocytes on blood film, not the specific drug-triggered, bite-cell/Heinz-body pattern described here.', 1),
('f3000000-0000-0000-0000-000000000006', 'B', 'Glucose-6-phosphate dehydrogenase (G6PD) deficiency', true, $x$Correct. Acute haemolysis triggered by an oxidative stressor (a sulfonamide antibiotic), with bite cells and Heinz bodies (denatured haemoglobin) on blood film, in a patient of a population with higher prevalence, is characteristic of G6PD deficiency, an X-linked enzyme deficiency impairing red cells' defence against oxidative stress.$x$, 2),
('f3000000-0000-0000-0000-000000000006', 'C', 'Autoimmune haemolytic anaemia', false, 'Ruled out because AIHA is typically confirmed by a positive direct antiglobulin (Coombs) test and does not classically show bite cells or Heinz bodies, which are specific to oxidative haemolysis in G6PD deficiency.', 3),
('f3000000-0000-0000-0000-000000000006', 'D', 'Sickle cell disease', false, 'Ruled out because sickle cell disease would show sickle cells on blood film, not the bite cells and Heinz bodies specific to G6PD deficiency.', 4),
('f3000000-0000-0000-0000-000000000006', 'E', 'Beta-thalassaemia major', false, 'Ruled out because thalassaemia major presents with severe chronic anaemia from birth/infancy, not this acute, drug-triggered haemolytic episode with the specific blood film findings described.', 5),
('f3000000-0000-0000-0000-000000000007', 'A', 'Iron deficiency anaemia', false, 'Ruled out because iron deficiency causes a low ferritin and raised (not reduced) TIBC, the opposite biochemical pattern to that described here.', 1),
('f3000000-0000-0000-0000-000000000007', 'B', 'Vitamin B12 deficiency', false, 'Ruled out because B12 deficiency causes a macrocytic (not normocytic) anaemia, an inconsistent picture with the normal MCV described here.', 2),
('f3000000-0000-0000-0000-000000000007', 'C', 'Haemolytic anaemia', false, 'Ruled out because haemolytic anaemia would typically show raised reticulocytes, raised bilirubin and LDH, not the iron study pattern described, which specifically reflects chronic disease-related iron sequestration.', 3),
('f3000000-0000-0000-0000-000000000007', 'D', 'Aplastic anaemia', false, 'Ruled out because aplastic anaemia typically causes pancytopenia (affecting all cell lines) from bone marrow failure, not an isolated mild normocytic anaemia with this specific iron study pattern.', 4),
('f3000000-0000-0000-0000-000000000007', 'E', 'Anaemia of chronic disease', true, 'Correct. A mild normocytic anaemia with normal or raised ferritin (an acute phase reactant) and reduced total iron-binding capacity, in a patient with an underlying chronic inflammatory condition (rheumatoid arthritis), is characteristic of anaemia of chronic disease, driven by hepcidin-mediated iron sequestration.', 5),
('f3000000-0000-0000-0000-000000000008', 'A', 'Reduced erythropoietin production from chronic kidney disease', true, 'Correct. In advanced chronic kidney disease, reduced renal production of erythropoietin (the hormone that stimulates red cell production in the bone marrow) is the primary cause of a normocytic anaemia with an inappropriately low reticulocyte count, with normal iron, B12 and folate excluding other common causes.', 1),
('f3000000-0000-0000-0000-000000000008', 'B', 'Iron deficiency', false, 'Ruled out because iron studies are reported as normal, excluding iron deficiency as the cause here.', 2),
('f3000000-0000-0000-0000-000000000008', 'C', 'Vitamin B12 deficiency', false, 'Ruled out because B12 levels are normal, and B12 deficiency would in any case cause a macrocytic, not normocytic, anaemia.', 3),
('f3000000-0000-0000-0000-000000000008', 'D', 'Folate deficiency', false, 'Ruled out because folate levels are normal, and folate deficiency would in any case cause a macrocytic, not normocytic, anaemia.', 4),
('f3000000-0000-0000-0000-000000000008', 'E', 'Chronic gastrointestinal blood loss', false, 'Ruled out because normal iron studies make ongoing significant blood loss (which would typically cause iron deficiency over time) less likely as the primary explanation here.', 5),
('f3000000-0000-0000-0000-000000000009', 'A', 'No significant long-term risk once the spleen is removed', false, 'Ruled out because splenectomy carries a well-recognised, significant lifelong infection risk that requires active, ongoing management, not simply being disregarded once the procedure is complete.', 1),
('f3000000-0000-0000-0000-000000000009', 'B', 'Increased risk of bleeding disorders unrelated to infection', false, 'Ruled out because the primary and most clinically significant long-term concern after splenectomy is infection risk from encapsulated organisms, not a bleeding disorder.', 2),
('f3000000-0000-0000-0000-000000000009', 'C', 'Increased lifelong risk of overwhelming infection with encapsulated organisms, requiring vaccination and antibiotic prophylaxis', true, 'Correct. Splenectomy significantly increases the lifelong risk of overwhelming post-splenectomy infection with encapsulated organisms (Streptococcus pneumoniae, Haemophilus influenzae, Neisseria meningitidis); patients require vaccination against these organisms and often long-term prophylactic antibiotics, along with patient education about seeking urgent medical attention for any fever.', 3),
('f3000000-0000-0000-0000-000000000009', 'D', 'Mandatory lifelong blood transfusions regardless of ongoing haemolysis', false, 'Ruled out because splenectomy is performed specifically to reduce haemolysis and transfusion requirement in conditions like hereditary spherocytosis, not to create a need for ongoing transfusion.', 4),
('f3000000-0000-0000-0000-000000000009', 'E', 'Complete resolution of all haematological abnormalities with no further monitoring needed', false, 'Ruled out because although splenectomy reduces haemolysis, the underlying red cell membrane defect remains, and patients still require follow-up along with the specific infection risk management described.', 5),
('f3000000-0000-0000-0000-000000000010', 'A', 'Hereditary spherocytosis', false, 'Ruled out because although hereditary spherocytosis also shows spherocytes and haemolysis markers, it would show a negative direct antiglobulin test, as it is a membrane defect, not an antibody-mediated process; the positive DAT here specifically confirms an autoimmune cause.', 1),
('f3000000-0000-0000-0000-000000000010', 'B', 'Iron deficiency anaemia', false, 'Ruled out because iron deficiency does not cause haemolysis, spherocytes, a positive DAT, or the raised LDH/low haptoglobin pattern seen here.', 2),
('f3000000-0000-0000-0000-000000000010', 'C', 'Thalassaemia', false, 'Ruled out because thalassaemia is a chronic, non-immune microcytic anaemia and would not show a positive direct antiglobulin test or this pattern of active haemolysis markers.', 3),
('f3000000-0000-0000-0000-000000000010', 'D', 'Autoimmune haemolytic anaemia', true, 'Correct. Anaemia with a raised reticulocyte count (marrow compensation), spherocytes on blood film, raised LDH, low haptoglobin (all reflecting active haemolysis), and a positive direct antiglobulin test (confirming an antibody-mediated process) together confirm autoimmune haemolytic anaemia.', 4),
('f3000000-0000-0000-0000-000000000010', 'E', 'Aplastic anaemia', false, 'Ruled out because aplastic anaemia causes pancytopenia from bone marrow failure with a low (not raised) reticulocyte count, the opposite pattern to the compensatory reticulocytosis seen here.', 5),
('f3000000-0000-0000-0000-000000000011', 'A', 'Acute myeloid leukaemia', false, 'Ruled out because although AML also causes pancytopenia with blasts, ALL is far more common in children and the marrow blast lineage described here is lymphoblastic, not myeloid.', 1),
('f3000000-0000-0000-0000-000000000011', 'B', 'Chronic lymphocytic leukaemia', false, 'Ruled out because CLL is a disease of older adults with a more indolent course and mature (not blast) lymphocytes, not the acute presentation with blast cells described in this child.', 2),
('f3000000-0000-0000-0000-000000000011', 'C', 'Infectious mononucleosis', false, 'Ruled out because although mononucleosis can cause fatigue and lymphocytosis, it does not cause pancytopenia with marrow blast infiltration; the bone marrow findings here are diagnostic of leukaemia.', 3),
('f3000000-0000-0000-0000-000000000011', 'D', 'Acute lymphoblastic leukaemia', true, 'Correct. Pancytopenia (from marrow infiltration crowding out normal haematopoiesis) with circulating blast cells, bone pain, and a marrow blast count above 20% (lymphoblasts specifically), in a young child, is characteristic of acute lymphoblastic leukaemia, the most common childhood malignancy.', 4),
('f3000000-0000-0000-0000-000000000011', 'E', 'Aplastic anaemia', false, 'Ruled out because aplastic anaemia causes pancytopenia from marrow hypoplasia without blast cells, the opposite bone marrow finding to the blast-rich picture described here.', 5),
('f3000000-0000-0000-0000-000000000012', 'A', 'Acute lymphoblastic leukaemia', false, 'Ruled out because Auer rods are specific to myeloid blasts and are not seen in lymphoblasts; their presence confirms AML rather than ALL.', 1),
('f3000000-0000-0000-0000-000000000012', 'B', 'Chronic myeloid leukaemia', false, 'Ruled out because CML presents with a chronic, marked leucocytosis with a full spectrum of maturing myeloid cells, not the acute pancytopenia with blast-predominant marrow seen in AML.', 2),
('f3000000-0000-0000-0000-000000000012', 'C', 'Acute myeloid leukaemia', true, 'Correct. Pancytopenia with circulating blasts and Auer rods (linear cytoplasmic inclusions of fused primary granules) seen within myeloblasts on bone marrow examination is diagnostic of acute myeloid leukaemia; Auer rods are pathognomonic for a myeloid (not lymphoid) blast lineage.', 3),
('f3000000-0000-0000-0000-000000000012', 'D', 'Myelodysplastic syndrome', false, 'Ruled out because although MDS can show dysplastic changes and can progress to AML, the marrow blast percentage and Auer rods described here confirm a diagnosis of acute leukaemia, not MDS.', 4),
('f3000000-0000-0000-0000-000000000012', 'E', 'Multiple myeloma', false, 'Ruled out because myeloma is a plasma cell malignancy, not a myeloblastic process, and would not show Auer rods, which are specific to myeloid blasts.', 5),
('f3000000-0000-0000-0000-000000000013', 'A', 'Simple thrombocytopenia from marrow infiltration alone', false, 'Ruled out because isolated thrombocytopenia would not explain the prolonged PT and APTT or the markedly low fibrinogen, which reflect a consumptive coagulopathy (DIC), not simply reduced platelet production.', 1),
('f3000000-0000-0000-0000-000000000013', 'B', 'Vitamin K deficiency', false, 'Ruled out because vitamin K deficiency causes an isolated prolongation of the PT (and later APTT) from reduced synthesis of vitamin K-dependent factors, without the low fibrinogen seen in DIC, and is not the classic association with APL.', 2),
('f3000000-0000-0000-0000-000000000013', 'C', 'Haemophilia A', false, 'Ruled out because haemophilia A is an inherited factor VIII deficiency causing an isolated prolonged APTT with normal PT and fibrinogen, not the combined coagulopathy described here, and is unrelated to a new leukaemia diagnosis.', 3),
('f3000000-0000-0000-0000-000000000013', 'D', 'Liver failure', false, 'Ruled out because although liver failure can cause a coagulopathy, there is no evidence of liver disease here, and the strong specific association between APL and DIC makes this the more likely explanation.', 4),
('f3000000-0000-0000-0000-000000000013', 'E', 'Disseminated intravascular coagulation', true, 'Correct. Acute promyelocytic leukaemia is strongly associated with disseminated intravascular coagulation, in which release of procoagulant material from leukaemic promyelocytes triggers widespread activation of coagulation, consuming clotting factors and platelets, producing a combination of bleeding and clotting with a prolonged PT/APTT and low fibrinogen.', 5),
('f3000000-0000-0000-0000-000000000014', 'A', 'Acute lymphoblastic leukaemia', false, 'Ruled out because ALL causes an acute presentation with pancytopenia and immature blast cells, not the indolent, mature lymphocyte picture with smudge cells described here.', 1),
('f3000000-0000-0000-0000-000000000014', 'B', 'Chronic lymphocytic leukaemia', true, 'Correct. An isolated, often incidentally discovered lymphocytosis of small, mature-appearing lymphocytes with characteristic smear (smudge) cells (fragile cells that rupture during film preparation) on blood film, in an older asymptomatic patient, is characteristic of chronic lymphocytic leukaemia, often diagnosed incidentally on routine bloods.', 2),
('f3000000-0000-0000-0000-000000000014', 'C', 'Infectious mononucleosis', false, 'Ruled out because although mononucleosis causes lymphocytosis, it typically presents acutely with fever, sore throat and lymphadenopathy in a younger patient, and shows atypical (reactive) lymphocytes, not the mature small lymphocytes with smudge cells seen in CLL.', 3),
('f3000000-0000-0000-0000-000000000014', 'D', 'Hairy cell leukaemia', false, 'Ruled out because hairy cell leukaemia shows characteristic hairy cytoplasmic projections on the abnormal cells, not the smudge cell pattern described here, which is specific to CLL.', 4),
('f3000000-0000-0000-0000-000000000014', 'E', 'Reactive lymphocytosis from a viral infection', false, 'Ruled out because there is no infective symptomatology described, and the specific finding of smudge cells in an asymptomatic older patient is characteristic of CLL rather than a reactive process.', 5),
('f3000000-0000-0000-0000-000000000015', 'A', 'Chronic myeloid leukaemia', true, 'Correct. Marked leucocytosis with a full spectrum of maturing granulocytes (rather than a predominance of blasts), massive splenomegaly, and the Philadelphia chromosome (BCR-ABL1 fusion gene from a t(9;22) translocation) together are diagnostic of chronic myeloid leukaemia, now effectively treated with tyrosine kinase inhibitors targeting the abnormal fusion protein.', 1),
('f3000000-0000-0000-0000-000000000015', 'B', 'Acute myeloid leukaemia', false, 'Ruled out because AML presents acutely with a predominance of immature blast cells and pancytopenia, not the chronic, full-spectrum granulocyte maturation pattern with massive splenomegaly described here.', 2),
('f3000000-0000-0000-0000-000000000015', 'C', 'Chronic lymphocytic leukaemia', false, 'Ruled out because CLL involves mature lymphocytes, not the myeloid lineage with the Philadelphia chromosome described here.', 3),
('f3000000-0000-0000-0000-000000000015', 'D', 'Myelofibrosis', false, 'Ruled out because although myelofibrosis can also cause massive splenomegaly, it typically shows a leucoerythroblastic blood film with teardrop poikilocytes and marrow fibrosis, not this specific Philadelphia chromosome-positive picture.', 4),
('f3000000-0000-0000-0000-000000000015', 'E', 'Polycythaemia vera', false, 'Ruled out because PV is characterised by a raised red cell mass (not primarily leucocytosis) and is typically associated with a JAK2 mutation, not the Philadelphia chromosome described here.', 5),
('f3000000-0000-0000-0000-000000000016', 'A', 'Non-Hodgkin lymphoma', false, 'Ruled out because Reed-Sternberg cells are specific to Hodgkin lymphoma; their presence excludes non-Hodgkin lymphoma, which lacks this characteristic cell type on histology.', 1),
('f3000000-0000-0000-0000-000000000016', 'B', 'Reactive lymphadenopathy from infection', false, 'Ruled out because reactive lymphadenopathy does not show Reed-Sternberg cells on biopsy, and the combination of B symptoms with this specific histological finding indicates malignancy, not a simple reactive process.', 2),
('f3000000-0000-0000-0000-000000000016', 'C', 'Tuberculous lymphadenitis', false, 'Ruled out because TB lymphadenitis shows caseating granulomas on biopsy, not Reed-Sternberg cells, which are specific to Hodgkin lymphoma.', 3),
('f3000000-0000-0000-0000-000000000016', 'D', 'Hodgkin lymphoma', true, $x$Correct. Painless lymphadenopathy with systemic 'B symptoms' (night sweats, weight loss, fever) and Reed-Sternberg cells (large, binucleate cells with prominent nucleoli, giving an 'owl's eye' appearance) on lymph node biopsy are diagnostic of Hodgkin lymphoma.$x$, 4),
('f3000000-0000-0000-0000-000000000016', 'E', 'Metastatic carcinoma to lymph nodes', false, 'Ruled out because metastatic carcinoma would show epithelial malignant cells on biopsy, not the specific Reed-Sternberg cells diagnostic of Hodgkin lymphoma.', 5),
('f3000000-0000-0000-0000-000000000017', 'A', 'Hodgkin lymphoma', false, 'Ruled out because the biopsy specifically lacks Reed-Sternberg cells, which are required for a diagnosis of Hodgkin lymphoma; their absence points to non-Hodgkin lymphoma instead.', 1),
('f3000000-0000-0000-0000-000000000017', 'B', 'Non-Hodgkin lymphoma (e.g. diffuse large B-cell lymphoma)', true, 'Correct. Rapidly progressive, multi-site lymphadenopathy with systemic symptoms, and lymph node biopsy showing sheets of large atypical lymphoid cells without Reed-Sternberg cells, is characteristic of an aggressive non-Hodgkin lymphoma such as diffuse large B-cell lymphoma.', 2),
('f3000000-0000-0000-0000-000000000017', 'C', 'Reactive lymphadenopathy', false, 'Ruled out because reactive lymphadenopathy would not show sheets of large atypical lymphoid cells on biopsy, which indicates a malignant, not reactive, process.', 3),
('f3000000-0000-0000-0000-000000000017', 'D', 'Chronic lymphocytic leukaemia/small lymphocytic lymphoma', false, 'Ruled out because CLL/SLL shows small, mature-appearing lymphocytes on histology and typically has a more indolent course, not the rapidly progressive large-cell picture described here.', 4),
('f3000000-0000-0000-0000-000000000017', 'E', 'Sarcoidosis', false, 'Ruled out because sarcoidosis shows non-caseating granulomas on biopsy, not sheets of large atypical lymphoid cells, which are diagnostic of a lymphoid malignancy.', 5),
('f3000000-0000-0000-0000-000000000018', 'A', 'Chemotherapy-induced nephrotoxicity unrelated to tumour lysis', false, 'Ruled out because the specific combination of electrolyte abnormalities (hyperkalaemia, hyperphosphataemia, hypocalcaemia) alongside AKI, occurring in this precise temporal pattern after starting treatment for a high-grade, rapidly proliferating lymphoma, is the classic signature of tumour lysis syndrome specifically.', 1),
('f3000000-0000-0000-0000-000000000018', 'B', 'Adrenal insufficiency', false, 'Ruled out because adrenal insufficiency causes hyponatraemia and hyperkalaemia but not the hyperphosphataemia and hypocalcaemia pattern seen here, which specifically reflects massive cellular content release.', 2),
('f3000000-0000-0000-0000-000000000018', 'C', 'Tumour lysis syndrome', true, 'Correct. The combination of acute kidney injury, hyperkalaemia, hyperphosphataemia and hypocalcaemia occurring shortly after starting chemotherapy for a bulky, rapidly proliferating malignancy is characteristic of tumour lysis syndrome, caused by massive, rapid release of intracellular contents (potassium, phosphate, uric acid) from dying tumour cells overwhelming renal excretory capacity.', 3),
('f3000000-0000-0000-0000-000000000018', 'D', 'Rhabdomyolysis unrelated to malignancy', false, 'Ruled out because although rhabdomyolysis can also cause hyperkalaemia and AKI, there is no history of muscle injury described, and the clear temporal relationship to starting chemotherapy for a bulky, proliferative malignancy points to tumour lysis syndrome.', 4),
('f3000000-0000-0000-0000-000000000018', 'E', 'Simple dehydration', false, 'Ruled out because dehydration alone would not explain the specific pattern of hyperkalaemia, hyperphosphataemia and hypocalcaemia seen here, which reflects massive cellular breakdown, not simply reduced renal perfusion.', 5),
('f3000000-0000-0000-0000-000000000019', 'A', 'Direct DNA cross-linking causing cell death', false, 'Ruled out because this describes the mechanism of alkylating agents (e.g. cyclophosphamide), not imatinib, which works via targeted kinase inhibition rather than direct DNA damage.', 1),
('f3000000-0000-0000-0000-000000000019', 'B', 'Inhibition of microtubule formation, preventing mitosis', false, 'Ruled out because this describes the mechanism of vinca alkaloids or taxanes, not imatinib, which specifically inhibits the BCR-ABL1 kinase.', 2),
('f3000000-0000-0000-0000-000000000019', 'C', 'Non-specific inhibition of all rapidly dividing cells', false, $x$Ruled out because imatinib's key advantage over traditional chemotherapy is its relative specificity for cells expressing the BCR-ABL1 fusion protein, rather than broadly targeting all dividing cells.$x$, 3),
('f3000000-0000-0000-0000-000000000019', 'D', 'Stimulation of the immune system to attack leukaemic cells', false, $x$Ruled out because this describes an immunotherapy mechanism, not the targeted molecular kinase inhibition that defines imatinib's action.$x$, 4),
('f3000000-0000-0000-0000-000000000019', 'E', 'Selective inhibition of the BCR-ABL1 tyrosine kinase', true, 'Correct. Imatinib is a tyrosine kinase inhibitor that selectively targets the abnormal BCR-ABL1 fusion protein produced by the Philadelphia chromosome, blocking its constitutive kinase activity that drives uncontrolled proliferation of the leukaemic clone in CML.', 5),
('f3000000-0000-0000-0000-000000000020', 'A', 'Hypogammaglobulinaemia secondary to CLL', true, 'Correct. Chronic lymphocytic leukaemia commonly causes secondary hypogammaglobulinaemia, as the malignant clonal B lymphocytes fail to function normally and suppress production of normal immunoglobulins, predisposing patients to recurrent bacterial infections; immunoglobulin replacement therapy may be considered in patients with recurrent significant infections.', 1),
('f3000000-0000-0000-0000-000000000020', 'B', 'Neutropenia from bone marrow infiltration alone', false, 'Ruled out because the specific laboratory finding described is reduced immunoglobulin levels, not a reported low neutrophil count; while marrow infiltration can also contribute to cytopenias in CLL, the described mechanism here relates to impaired antibody production.', 2),
('f3000000-0000-0000-0000-000000000020', 'C', 'Normal age-related decline in immune function', false, 'Ruled out because the degree of immunoglobulin reduction and the specific association with CLL indicates a disease-related, not simply age-related, cause of increased infection susceptibility.', 3),
('f3000000-0000-0000-0000-000000000020', 'D', 'Unrelated primary immunodeficiency', false, $x$Ruled out because the hypogammaglobulinaemia here is a well-recognised secondary complication of the patient's known CLL, not a coincidental separate primary immunodeficiency.$x$, 4),
('f3000000-0000-0000-0000-000000000020', 'E', 'Vitamin deficiency causing immune dysfunction', false, 'Ruled out because there is no evidence of a specific vitamin deficiency described, and the pattern of globally reduced immunoglobulins in a patient with CLL points to disease-related hypogammaglobulinaemia.', 5),
('f3000000-0000-0000-0000-000000000021', 'A', 'Haemophilia B', false, 'Ruled out because haemophilia B is caused by factor IX deficiency, not factor VIII; the specific factor assay described here confirms haemophilia A.', 1),
('f3000000-0000-0000-0000-000000000021', 'B', 'Von Willebrand disease', false, 'Ruled out because although vWD can also prolong the APTT (via reduced factor VIII, which is stabilised by von Willebrand factor), it typically presents with mucocutaneous bleeding (epistaxis, menorrhagia) rather than the haemarthroses classic for haemophilia, and factor VIII reduction here is markedly severe, consistent with haemophilia A rather than vWD.', 2),
('f3000000-0000-0000-0000-000000000021', 'C', 'Vitamin K deficiency', false, 'Ruled out because vitamin K deficiency causes a prolonged PT (from reduced factors II, VII, IX, X) typically before APTT, not this isolated APTT prolongation with specifically reduced factor VIII.', 3),
('f3000000-0000-0000-0000-000000000021', 'D', 'Disseminated intravascular coagulation', false, 'Ruled out because DIC causes prolongation of both PT and APTT with low fibrinogen and low platelets in an acutely unwell patient, not this isolated, lifelong pattern of factor VIII deficiency.', 4),
('f3000000-0000-0000-0000-000000000021', 'E', 'Haemophilia A', true, 'Correct. An isolated prolonged APTT with normal PT, markedly reduced factor VIII activity, and a history of haemarthroses and prolonged bleeding after minor trauma in a boy (X-linked inheritance) is characteristic of haemophilia A, a deficiency of factor VIII.', 5),
('f3000000-0000-0000-0000-000000000022', 'A', 'Haemophilia A', false, 'Ruled out because haemophilia A predominantly affects males (X-linked) and classically causes haemarthroses rather than the mucocutaneous bleeding pattern (menorrhagia, easy bruising) described here, which is more typical of vWD.', 1),
('f3000000-0000-0000-0000-000000000022', 'B', 'Von Willebrand disease', true, 'Correct. Mucocutaneous bleeding (menorrhagia, easy bruising, prolonged bleeding after dental procedures) since a young age, with reduced von Willebrand factor antigen and activity, is characteristic of von Willebrand disease, the most common inherited bleeding disorder, caused by deficiency or dysfunction of von Willebrand factor.', 2),
('f3000000-0000-0000-0000-000000000022', 'C', 'Immune thrombocytopenic purpura', false, 'Ruled out because ITP causes isolated thrombocytopenia with a normal APTT, not the specific reduction in von Willebrand factor described here.', 3),
('f3000000-0000-0000-0000-000000000022', 'D', 'Factor XI deficiency', false, 'Ruled out because although factor XI deficiency also prolongs the APTT, the specific finding of reduced von Willebrand factor antigen and activity confirms von Willebrand disease as the diagnosis.', 4),
('f3000000-0000-0000-0000-000000000022', 'E', 'Vitamin K deficiency', false, 'Ruled out because vitamin K deficiency causes reduced factors II, VII, IX and X with a prolonged PT, not the specific von Willebrand factor deficiency described here.', 5),
('f3000000-0000-0000-0000-000000000023', 'A', 'Haemophilia A', false, 'Ruled out because haemophilia A is an isolated, inherited factor VIII deficiency, not an acute, acquired, multi-factor consumptive coagulopathy triggered by sepsis as described here.', 1),
('f3000000-0000-0000-0000-000000000023', 'B', 'Immune thrombocytopenic purpura', false, 'Ruled out because ITP causes isolated thrombocytopenia with normal PT, APTT and fibrinogen, not the global coagulopathy described here.', 2),
('f3000000-0000-0000-0000-000000000023', 'C', 'Vitamin K deficiency alone', false, 'Ruled out because vitamin K deficiency causes an isolated prolonged PT (and later APTT) without the low fibrinogen, thrombocytopenia and markedly raised D-dimer seen in DIC.', 3),
('f3000000-0000-0000-0000-000000000023', 'D', 'Disseminated intravascular coagulation', true, 'Correct. Simultaneous bleeding and microvascular thrombosis, with prolonged PT and APTT, low fibrinogen, thrombocytopenia and markedly raised D-dimer, in the context of severe sepsis, is characteristic of disseminated intravascular coagulation, a consumptive coagulopathy triggered by widespread activation of the coagulation cascade.', 4),
('f3000000-0000-0000-0000-000000000023', 'E', 'Thrombotic thrombocytopenic purpura', false, 'Ruled out because TTP typically shows normal coagulation studies (PT, APTT, fibrinogen) with microangiopathic haemolysis, unlike the deranged global coagulation profile described here, which is specific to DIC.', 5),
('f3000000-0000-0000-0000-000000000024', 'A', 'Immune thrombocytopenic purpura', true, 'Correct. Isolated, severe thrombocytopenia with normal coagulation studies, following a preceding viral infection, and without splenomegaly, is characteristic of immune thrombocytopenic purpura, caused by antibody-mediated platelet destruction.', 1),
('f3000000-0000-0000-0000-000000000024', 'B', 'Disseminated intravascular coagulation', false, 'Ruled out because DIC causes a global coagulopathy with prolonged PT and APTT and low fibrinogen alongside thrombocytopenia, not the isolated, normal-coagulation-study picture described here.', 2),
('f3000000-0000-0000-0000-000000000024', 'C', 'Von Willebrand disease', false, 'Ruled out because vWD typically causes a mildly prolonged APTT with normal platelet count, not the severe isolated thrombocytopenia described here.', 3),
('f3000000-0000-0000-0000-000000000024', 'D', 'Haemophilia A', false, 'Ruled out because haemophilia A causes a prolonged APTT with normal platelet count, the opposite pattern to this isolated thrombocytopenia with normal coagulation studies.', 4),
('f3000000-0000-0000-0000-000000000024', 'E', 'Hypersplenism causing thrombocytopenia', false, 'Ruled out because there is no splenomegaly described, making hypersplenism-related platelet sequestration an unlikely explanation for this degree of isolated thrombocytopenia.', 5),
('f3000000-0000-0000-0000-000000000025', 'A', 'Disseminated intravascular coagulation', false, 'Ruled out because DIC characteristically shows deranged coagulation studies (prolonged PT/APTT, low fibrinogen), unlike the normal coagulation profile described here, which is a key feature distinguishing TTP from DIC despite both causing thrombocytopenia and organ dysfunction.', 1),
('f3000000-0000-0000-0000-000000000025', 'B', 'Immune thrombocytopenic purpura', false, 'Ruled out because ITP causes isolated thrombocytopenia without haemolysis or schistocytes on blood film, unlike the microangiopathic haemolytic picture described here.', 2),
('f3000000-0000-0000-0000-000000000025', 'C', 'Thrombotic thrombocytopenic purpura', true, 'Correct. Microangiopathic haemolytic anaemia (schistocytes, evidence of haemolysis), severe thrombocytopenia, neurological symptoms (confusion), fever and renal impairment, with normal coagulation studies (distinguishing it from DIC), is characteristic of thrombotic thrombocytopenic purpura, caused by a severe deficiency of ADAMTS13, requiring urgent plasma exchange.', 3),
('f3000000-0000-0000-0000-000000000025', 'D', 'Haemolytic uraemic syndrome', false, 'Ruled out because although HUS shares features with TTP (microangiopathic haemolysis, thrombocytopenia, renal impairment), it typically follows a diarrhoeal illness (often in children) and does not classically feature the prominent neurological symptoms and fever seen here, which are more characteristic of TTP.', 4),
('f3000000-0000-0000-0000-000000000025', 'E', 'Vitamin B12 deficiency', false, 'Ruled out because B12 deficiency does not cause thrombocytopenia with schistocytes or the acute multi-organ presentation described; it causes a macrocytic anaemia without this microangiopathic picture.', 5),
('f3000000-0000-0000-0000-000000000026', 'A', 'Withholding warfarin alone, with no active reversal', false, 'Ruled out because simply withholding warfarin does not provide rapid enough correction for major, life-threatening bleeding; active reversal with vitamin K and PCC is required.', 1),
('f3000000-0000-0000-0000-000000000026', 'B', 'IV vitamin K and prothrombin complex concentrate', true, 'Correct. In major bleeding with a significantly elevated INR on warfarin, immediate reversal with IV vitamin K (to restore synthesis of vitamin K-dependent clotting factors) and prothrombin complex concentrate (providing immediate replacement of factors II, VII, IX and X) is the standard emergency management to rapidly correct the coagulopathy.', 2),
('f3000000-0000-0000-0000-000000000026', 'C', 'Oral vitamin K alone, without prothrombin complex concentrate', false, 'Ruled out because oral vitamin K takes longer to act and does not provide the immediate factor replacement needed for major bleeding; IV vitamin K combined with PCC provides more rapid, complete reversal.', 3),
('f3000000-0000-0000-0000-000000000026', 'D', 'Fresh frozen plasma alone as the definitive treatment', false, 'Ruled out because although FFP can be used if PCC is unavailable, PCC is preferred for warfarin reversal in major bleeding as it provides a more concentrated, rapid and reliable correction of the specific deficient factors.', 4),
('f3000000-0000-0000-0000-000000000026', 'E', 'Protamine sulfate', false, 'Ruled out because protamine sulfate reverses heparin, not warfarin; it has no role in reversing vitamin K antagonist-related coagulopathy.', 5),
('f3000000-0000-0000-0000-000000000027', 'A', 'Vitamin K is a cofactor for carboxylation of glutamate residues on factors II, VII, IX and X, required for their functional activity', true, 'Correct. Vitamin K acts as a cofactor for the hepatic gamma-carboxylation of glutamate residues on clotting factors II, VII, IX and X (and proteins C and S), a modification essential for these factors to bind calcium and function normally in the coagulation cascade; warfarin works by inhibiting vitamin K recycling, and administering vitamin K restores the substrate needed for this process.', 1),
('f3000000-0000-0000-0000-000000000027', 'B', 'Vitamin K directly activates platelets to promote clot formation', false, $x$Ruled out because vitamin K's role is in the hepatic synthesis of specific clotting factors via carboxylation, not direct platelet activation.$x$, 2),
('f3000000-0000-0000-0000-000000000027', 'C', 'Vitamin K inhibits fibrinolysis to stabilise existing clots', false, 'Ruled out because vitamin K does not act on the fibrinolytic system; its role is upstream, in the synthesis of functional clotting factors.', 3),
('f3000000-0000-0000-0000-000000000027', 'D', 'Vitamin K binds directly to warfarin, neutralising it in the bloodstream', false, $x$Ruled out because vitamin K does not directly neutralise warfarin; rather, it restores the substrate pool needed for clotting factor carboxylation, which warfarin's inhibition of vitamin K recycling had depleted.$x$, 4),
('f3000000-0000-0000-0000-000000000027', 'E', 'Vitamin K increases hepatic blood flow to enhance clotting factor delivery', false, $x$Ruled out because this does not reflect vitamin K's actual biochemical role, which is as a specific cofactor for post-translational modification of clotting factors, not a haemodynamic effect.$x$, 5),
('f3000000-0000-0000-0000-000000000028', 'A', 'Factor VIII deficiency (haemophilia A)', false, 'Ruled out because a factor deficiency would correct on mixing with normal plasma (which supplies the missing factor), unlike the failure to correct described here, which indicates an inhibitor rather than a deficiency.', 1),
('f3000000-0000-0000-0000-000000000028', 'B', 'Vitamin K deficiency', false, 'Ruled out because vitamin K deficiency causes a factor deficiency pattern that would correct on a mixing study, not the failure to correct seen here, which points to an inhibitor.', 2),
('f3000000-0000-0000-0000-000000000028', 'C', 'Von Willebrand disease', false, 'Ruled out because vWD reflects reduced or dysfunctional von Willebrand factor (a deficiency-type pattern), which would be expected to correct on mixing, not the inhibitor pattern described.', 3),
('f3000000-0000-0000-0000-000000000028', 'D', 'Laboratory error requiring no further action', false, 'Ruled out because a mixing study failing to correct is a recognised, meaningful diagnostic pattern (indicating an inhibitor) rather than simply reflecting a testing artefact, especially given the strongly compatible clinical history.', 4),
('f3000000-0000-0000-0000-000000000028', 'E', 'Presence of lupus anticoagulant (an inhibitor)', true, 'Correct. A prolonged APTT that fails to correct when mixed with normal plasma indicates the presence of an inhibitor (rather than a simple factor deficiency, which would correct with mixing); in a patient with recurrent miscarriage and unprovoked thrombosis, this is characteristic of lupus anticoagulant, part of antiphospholipid syndrome, which paradoxically prolongs the APTT in vitro while being clinically prothrombotic in vivo.', 5),
('f3000000-0000-0000-0000-000000000029', 'A', 'Regular INR monitoring, as with warfarin', false, 'Ruled out because INR is specifically calibrated to monitor vitamin K antagonists like warfarin; it is not a reliable or appropriate test for monitoring DOACs such as rivaroxaban.', 1),
('f3000000-0000-0000-0000-000000000029', 'B', 'Daily APTT monitoring', false, 'Ruled out because routine APTT monitoring is not required for DOACs, which have predictable dose-response relationships not requiring this type of regular laboratory titration.', 2),
('f3000000-0000-0000-0000-000000000029', 'C', 'Routine coagulation monitoring is not required for direct oral anticoagulants such as rivaroxaban', true, 'Correct. Direct oral anticoagulants (including rivaroxaban, a factor Xa inhibitor) have predictable pharmacokinetics and do not require routine coagulation monitoring, unlike warfarin, which requires regular INR checks; this is one of their key practical advantages, though renal function should still be monitored periodically as clearance can be affected by renal impairment.', 3),
('f3000000-0000-0000-0000-000000000029', 'D', 'Weekly platelet count monitoring specifically for anticoagulation control', false, 'Ruled out because platelet count does not reflect anticoagulant effect and is not used to monitor or titrate DOAC therapy.', 4),
('f3000000-0000-0000-0000-000000000029', 'E', 'Monthly bleeding time testing', false, 'Ruled out because bleeding time is an outdated, poorly reproducible test not used to monitor any modern anticoagulant, including DOACs.', 5),
('f3000000-0000-0000-0000-000000000030', 'A', 'Disseminated intravascular coagulation', false, 'Ruled out because DIC would typically show a deranged coagulation profile (prolonged PT/APTT, low fibrinogen) alongside thrombocytopenia, and would not have this specific temporal relationship to heparin exposure with paradoxical new thrombosis.', 1),
('f3000000-0000-0000-0000-000000000030', 'B', 'Immune thrombocytopenic purpura', false, 'Ruled out because ITP is not specifically linked to heparin exposure in this characteristic timeframe, and does not typically present with new thrombosis, unlike the paradoxical thrombotic tendency of HIT.', 2),
('f3000000-0000-0000-0000-000000000030', 'C', 'Normal expected effect of heparin requiring no action', false, 'Ruled out because a significant platelet drop with new thrombosis on heparin is not a benign expected effect; it requires immediate recognition and action given the serious risk of further, potentially life- or limb-threatening thrombosis.', 3),
('f3000000-0000-0000-0000-000000000030', 'D', 'Heparin-induced thrombocytopenia', true, 'Correct. A falling platelet count typically 5-10 days after starting heparin, paradoxically accompanied by new thrombosis (rather than bleeding), is characteristic of heparin-induced thrombocytopenia, an immune-mediated reaction to heparin-platelet factor 4 complexes; heparin must be stopped immediately and an alternative (non-heparin) anticoagulant started given the high thrombotic risk.', 4),
('f3000000-0000-0000-0000-000000000030', 'E', 'Thrombotic thrombocytopenic purpura', false, 'Ruled out because TTP is not specifically triggered by heparin exposure and would show microangiopathic haemolysis (schistocytes) on blood film, not described here; the clear temporal relationship to heparin points to HIT.', 5),
('f3000000-0000-0000-0000-000000000031', 'A', 'Secondary polycythaemia (e.g. from chronic hypoxia)', false, 'Ruled out because secondary polycythaemia is driven by raised erythropoietin (e.g. from hypoxia or an EPO-secreting tumour) and would not show the JAK2 mutation, which is specific to the primary, clonal process of polycythaemia vera.', 1),
('f3000000-0000-0000-0000-000000000031', 'B', 'Relative (apparent) polycythaemia from dehydration', false, 'Ruled out because relative polycythaemia reflects reduced plasma volume with a normal total red cell mass, and would not be associated with a positive JAK2 mutation or the classic symptom of aquagenic pruritus.', 2),
('f3000000-0000-0000-0000-000000000031', 'C', 'Essential thrombocythaemia', false, 'Ruled out because although ET can also be JAK2-positive, it is characterised primarily by marked thrombocytosis without the significantly raised haemoglobin/haematocrit and plethora seen here, which are the dominant features of PV.', 3),
('f3000000-0000-0000-0000-000000000031', 'D', 'Chronic myeloid leukaemia', false, 'Ruled out because CML is characterised by marked leucocytosis and the Philadelphia chromosome, not primarily by raised haemoglobin with JAK2 positivity.', 4),
('f3000000-0000-0000-0000-000000000031', 'E', 'Polycythaemia vera', true, 'Correct. A raised haemoglobin/haematocrit with plethora, aquagenic pruritus (itching after a hot bath, a classically described symptom), mild thrombocytosis, and a positive JAK2 V617F mutation together confirm polycythaemia vera, a myeloproliferative neoplasm characterised by clonal overproduction of red cells.', 5),
('f3000000-0000-0000-0000-000000000032', 'A', 'Spontaneous bleeding as the predominant risk', false, 'Ruled out because although very high platelet counts can occasionally cause acquired von Willebrand-type bleeding in extreme thrombocytosis, the predominant and most clinically significant risk in PV overall is thrombosis, not bleeding.', 1),
('f3000000-0000-0000-0000-000000000032', 'B', 'Arterial and venous thrombosis', true, 'Correct. The increased red cell mass and blood viscosity in polycythaemia vera significantly raise the risk of both arterial (e.g. stroke, myocardial infarction) and venous (e.g. DVT, PE, and atypical sites such as hepatic vein thrombosis/Budd-Chiari syndrome) thrombosis, making thrombosis prevention (venesection to maintain haematocrit below target, aspirin, and cytoreductive therapy in higher-risk patients) a central part of management.', 2),
('f3000000-0000-0000-0000-000000000032', 'C', 'Immediate risk of overwhelming bacterial infection', false, 'Ruled out because PV is not primarily associated with increased infection risk in the way that, for example, asplenia or neutropenia are; the dominant complication risk is thrombotic.', 3),
('f3000000-0000-0000-0000-000000000032', 'D', 'Progressive renal failure as the primary complication', false, 'Ruled out because although long-term complications of PV can include transformation to myelofibrosis or, rarely, acute leukaemia, renal failure is not the primary or most characteristic complication being highlighted here; thrombosis is the dominant near-term risk.', 4),
('f3000000-0000-0000-0000-000000000032', 'E', 'Guaranteed transformation to acute leukaemia within one year', false, 'Ruled out because although PV carries a small long-term risk of transformation to acute leukaemia or myelofibrosis over many years, this is not the primary near-term risk, and transformation is not universal or expected within one year.', 5),
('f3000000-0000-0000-0000-000000000033', 'A', 'Essential thrombocythaemia', true, 'Correct. A markedly raised, persistent platelet count, with a positive JAK2 mutation and exclusion of secondary (reactive) causes of thrombocytosis, confirms essential thrombocythaemia, a myeloproliferative neoplasm with clonal platelet overproduction.', 1),
('f3000000-0000-0000-0000-000000000033', 'B', 'Reactive thrombocytosis', false, 'Ruled out because secondary/reactive causes (iron deficiency, infection, inflammation, malignancy, post-splenectomy) have specifically been excluded, and the positive JAK2 mutation supports a primary, clonal process instead.', 2),
('f3000000-0000-0000-0000-000000000033', 'C', 'Polycythaemia vera', false, 'Ruled out because PV is characterised primarily by a raised red cell mass/haemoglobin, not the isolated marked thrombocytosis described here, though both conditions can be JAK2-positive.', 3),
('f3000000-0000-0000-0000-000000000033', 'D', 'Chronic myeloid leukaemia', false, 'Ruled out because CML is characterised by marked leucocytosis and the Philadelphia chromosome (BCR-ABL1), not primarily isolated thrombocytosis with JAK2 positivity.', 4),
('f3000000-0000-0000-0000-000000000033', 'E', 'Myelodysplastic syndrome', false, 'Ruled out because MDS typically causes cytopenias (not thrombocytosis) from ineffective haematopoiesis, the opposite pattern to the marked thrombocytosis described here.', 5),
('f3000000-0000-0000-0000-000000000034', 'A', 'Chronic myeloid leukaemia', false, 'Ruled out because CML classically shows a markedly raised white cell count with a full spectrum of maturing granulocytes and the Philadelphia chromosome, not the marrow fibrosis and dry tap described here.', 1),
('f3000000-0000-0000-0000-000000000034', 'B', 'Polycythaemia vera', false, 'Ruled out because PV is characterised by a raised red cell mass, not the marrow fibrosis, dry tap and teardrop poikilocytes described here (though PV can occasionally progress to secondary myelofibrosis over time).', 2),
('f3000000-0000-0000-0000-000000000034', 'C', 'Aplastic anaemia', false, 'Ruled out because aplastic anaemia causes marrow hypoplasia (empty marrow) rather than fibrosis, and does not typically cause massive splenomegaly or a leucoerythroblastic film with teardrop cells.', 3),
('f3000000-0000-0000-0000-000000000034', 'D', 'Primary myelofibrosis', true, $x$Correct. Massive splenomegaly (from extramedullary haematopoiesis), a leucoerythroblastic blood film with teardrop poikilocytes (red cells deformed while squeezing through fibrotic marrow), and a 'dry tap' on marrow aspiration with fibrosis confirmed on trephine biopsy are characteristic of primary myelofibrosis, a myeloproliferative neoplasm causing progressive bone marrow fibrosis.$x$, 4),
('f3000000-0000-0000-0000-000000000034', 'E', 'Acute myeloid leukaemia', false, 'Ruled out because AML presents acutely with marrow blast infiltration (not fibrosis), and would show blasts rather than the teardrop poikilocyte, leucoerythroblastic pattern described here.', 5),
('f3000000-0000-0000-0000-000000000035', 'A', 'Curing the underlying clonal disorder', false, 'Ruled out because venesection is a symptomatic and risk-reduction measure, not a curative treatment for the underlying clonal JAK2-driven myeloproliferative process.', 1),
('f3000000-0000-0000-0000-000000000035', 'B', 'Directly reducing platelet count', false, 'Ruled out because venesection specifically removes red cells (reducing red cell mass and haematocrit); it does not directly target platelet count, which is addressed separately if significantly elevated.', 2),
('f3000000-0000-0000-0000-000000000035', 'C', 'Reducing blood viscosity and thrombotic risk by lowering the red cell mass', true, 'Correct. Venesection reduces the total red cell mass and blood viscosity in polycythaemia vera, directly lowering the significantly increased risk of thrombosis (both arterial and venous) associated with this condition, making it a first-line management strategy alongside low-dose aspirin.', 3),
('f3000000-0000-0000-0000-000000000035', 'D', 'Preventing progression to acute leukaemia', false, $x$Ruled out because although this is a long-term concern in PV, venesection's primary and immediate rationale is reducing thrombotic risk through haematocrit control, not specifically preventing leukaemic transformation.$x$, 4),
('f3000000-0000-0000-0000-000000000035', 'E', 'Treating symptomatic anaemia', false, 'Ruled out because polycythaemia vera causes an excess, not deficiency, of red cells; venesection removes blood to reduce this excess, the opposite of anaemia treatment.', 5),
('f3000000-0000-0000-0000-000000000036', 'A', 'Simple undertreatment of his polycythaemia vera', false, 'Ruled out because the described findings (worsening anaemia, increasing splenomegaly, leucoerythroblastic film) reflect a distinct disease transformation process (myelofibrosis), not simply inadequate control of the original erythrocytosis.', 1),
('f3000000-0000-0000-0000-000000000036', 'B', 'Development of unrelated iron deficiency anaemia', false, 'Ruled out because iron deficiency would not explain the leucoerythroblastic blood film, teardrop cells or increasing splenomegaly, which together indicate marrow fibrosis rather than simple iron deficiency.', 2),
('f3000000-0000-0000-0000-000000000036', 'C', 'Transformation to post-polycythaemic myelofibrosis', true, $x$Correct. Longstanding polycythaemia vera can progress ('spent phase') to secondary (post-polycythaemic) myelofibrosis, characterised by worsening anaemia (as red cell overproduction gives way to marrow failure), increasing splenomegaly, and a leucoerythroblastic blood film with teardrop cells, reflecting the same marrow fibrosis process seen in primary myelofibrosis.$x$, 3),
('f3000000-0000-0000-0000-000000000036', 'D', 'New, unrelated chronic kidney disease', false, 'Ruled out because the specific blood film and splenomegaly findings point to a haematological transformation process, not a renal cause of anaemia.', 4),
('f3000000-0000-0000-0000-000000000036', 'E', 'Resolution of the underlying polycythaemia vera', false, 'Ruled out because these findings represent disease progression to a more advanced, fibrotic phase, not resolution or cure of the underlying condition.', 5),
('f3000000-0000-0000-0000-000000000037', 'A', 'Acquired von Willebrand syndrome from very high platelet count adsorbing von Willebrand factor multimers', true, 'Correct. At very high platelet counts (often above 1000x10^9/L), excessive adsorption and proteolysis of high-molecular-weight von Willebrand factor multimers onto the abnormally numerous platelets can cause an acquired form of von Willebrand syndrome, paradoxically increasing bleeding risk despite the high platelet count -- an important and counterintuitive complication of extreme thrombocytosis.', 1),
('f3000000-0000-0000-0000-000000000037', 'B', 'Simple platelet dysfunction unrelated to von Willebrand factor', false, 'Ruled out because although qualitative platelet dysfunction can occur in myeloproliferative disorders, the specific, well-recognised mechanism at very high platelet counts relates to acquired von Willebrand factor deficiency from multimer adsorption.', 2),
('f3000000-0000-0000-0000-000000000037', 'C', 'Coexistent inherited haemophilia', false, 'Ruled out because there is no suggestion of a separate inherited bleeding disorder; the bleeding tendency here is a recognised acquired complication directly related to the extreme thrombocytosis itself.', 3),
('f3000000-0000-0000-0000-000000000037', 'D', 'Vitamin K deficiency', false, 'Ruled out because there is no indication of vitamin K deficiency, and the bleeding tendency at extreme platelet counts in ET has a specific, well-documented mechanism related to von Willebrand factor.', 4),
('f3000000-0000-0000-0000-000000000037', 'E', 'Warfarin overdose', false, 'Ruled out because there is no mention of warfarin use, and the bleeding tendency described is a recognised intrinsic complication of extreme thrombocytosis, not related to anticoagulant medication.', 5),
('f3000000-0000-0000-0000-000000000038', 'A', 'High-dose corticosteroids as cytoreductive therapy', false, 'Ruled out because corticosteroids are not used as cytoreductive therapy in polycythaemia vera; hydroxycarbamide is the standard first-line agent for this purpose.', 1),
('f3000000-0000-0000-0000-000000000038', 'B', 'IV iron supplementation', false, 'Ruled out because iron supplementation would increase, not reduce, red cell production, the opposite of what is needed in polycythaemia vera; iron is actually often restricted or avoided in these patients.', 2),
('f3000000-0000-0000-0000-000000000038', 'C', 'Erythropoietin injections', false, 'Ruled out because erythropoietin would stimulate further red cell production, worsening polycythaemia vera rather than treating it.', 3),
('f3000000-0000-0000-0000-000000000038', 'D', 'Broad-spectrum antibiotics', false, 'Ruled out because there is no infective indication described, and antibiotics have no role in the cytoreductive management of polycythaemia vera.', 4),
('f3000000-0000-0000-0000-000000000038', 'E', 'Hydroxycarbamide', true, 'Correct. Hydroxycarbamide (hydroxyurea) is commonly used as first-line cytoreductive therapy in higher-risk polycythaemia vera (e.g. older age, prior thrombosis), working to reduce red cell, white cell and platelet production, used alongside venesection and low-dose aspirin to further reduce thrombotic risk.', 5),
('f3000000-0000-0000-0000-000000000039', 'A', 'Simple viral hepatitis, requiring no further haematological workup', false, 'Ruled out because viral hepatitis does not cause hepatic vein thrombosis on Doppler imaging; the specific finding of venous thrombosis at this atypical site should prompt investigation for an underlying prothrombotic condition, particularly a myeloproliferative neoplasm.', 1),
('f3000000-0000-0000-0000-000000000039', 'B', 'Budd-Chiari syndrome, prompting screening for an underlying myeloproliferative neoplasm (e.g. via JAK2 mutation testing)', true, 'Correct. Hepatic vein thrombosis (Budd-Chiari syndrome) causing abdominal pain, ascites and hepatomegaly is strongly associated with underlying myeloproliferative neoplasms (particularly polycythaemia vera and essential thrombocythaemia), even when the blood count itself may appear only mildly abnormal or masked by haemodilution from ascites; JAK2 mutation testing is an important part of the underlying cause workup.', 2),
('f3000000-0000-0000-0000-000000000039', 'C', 'Cholecystitis, requiring surgical referral only', false, 'Ruled out because cholecystitis does not cause hepatic vein thrombosis; the imaging finding described is specific to Budd-Chiari syndrome, not gallbladder disease.', 3),
('f3000000-0000-0000-0000-000000000039', 'D', 'Simple decompensated alcoholic liver disease, requiring no vascular workup', false, 'Ruled out because the specific finding of hepatic vein thrombosis on Doppler indicates a vascular, thrombotic process requiring investigation for an underlying cause, not simply a diagnosis of decompensated liver disease from alcohol without further workup.', 4),
('f3000000-0000-0000-0000-000000000039', 'E', 'Acute pancreatitis, unrelated to venous thrombosis', false, 'Ruled out because the imaging finding described is specific to hepatic vein thrombosis, not pancreatic inflammation.', 5),
('f3000000-0000-0000-0000-000000000040', 'A', 'High-dose warfarin as first-line therapy', false, 'Ruled out because warfarin is not standard first-line therapy for reducing thrombotic risk in ET; low-dose aspirin (and cytoreductive therapy in higher-risk patients) is the standard approach.', 1),
('f3000000-0000-0000-0000-000000000040', 'B', 'Immediate cytoreductive chemotherapy for all patients regardless of risk', false, $x$Ruled out because cytoreductive therapy is reserved for higher-risk patients, not given routinely to all ET patients regardless of risk stratification; this patient's specific risk factors should guide whether cytoreductive therapy is added.$x$, 2),
('f3000000-0000-0000-0000-000000000040', 'C', 'No treatment required at any platelet count', false, 'Ruled out because even in lower-risk ET, low-dose aspirin is typically still recommended to reduce thrombotic risk, rather than no treatment at all.', 3),
('f3000000-0000-0000-0000-000000000040', 'D', 'Low-dose aspirin', true, 'Correct. In essential thrombocythaemia, low-dose aspirin is standard first-line therapy to reduce thrombotic risk, particularly in patients without high-risk features; cytoreductive therapy is added for those at higher risk (older age, prior thrombosis, very high platelet count, or additional cardiovascular risk factors).', 4),
('f3000000-0000-0000-0000-000000000040', 'E', 'Routine platelet transfusion to normalise the count', false, 'Ruled out because platelet transfusion would inappropriately add more platelets to an already elevated count, and is not used to manage ET; the goal is to reduce thrombotic risk, not administer additional platelets.', 5),
('f3000000-0000-0000-0000-000000000041', 'A', 'Febrile non-haemolytic transfusion reaction', false, 'Ruled out because a febrile non-haemolytic reaction causes fever and chills without the haemodynamic compromise, loin pain or haemoglobinuria seen in a true haemolytic reaction.', 1),
('f3000000-0000-0000-0000-000000000041', 'B', 'Acute haemolytic transfusion reaction', true, 'Correct. Rapid onset of fever, loin pain, hypotension and haemoglobinuria (dark urine) within minutes of starting a transfusion is characteristic of an acute haemolytic transfusion reaction, most commonly caused by ABO incompatibility from a clerical or identification error, causing massive intravascular haemolysis; the transfusion must be stopped immediately and supportive treatment given.', 2),
('f3000000-0000-0000-0000-000000000041', 'C', 'Transfusion-associated circulatory overload', false, 'Ruled out because TACO presents with signs of fluid overload (breathlessness, hypertension, pulmonary oedema), not the haemolysis-specific features (loin pain, haemoglobinuria) described here.', 3),
('f3000000-0000-0000-0000-000000000041', 'D', 'Transfusion-related acute lung injury', false, 'Ruled out because TRALI presents with acute respiratory distress and hypoxia, not the specific haemolytic features (dark urine, loin pain) described here.', 4),
('f3000000-0000-0000-0000-000000000041', 'E', 'Allergic transfusion reaction', false, 'Ruled out because a simple allergic reaction typically causes urticaria and itching, not the severe haemodynamic compromise and haemolysis-specific features described here.', 5),
('f3000000-0000-0000-0000-000000000042', 'A', 'Transfusion-related acute lung injury', false, 'Ruled out because TRALI classically causes hypotension (not hypertension) alongside acute lung injury, and is thought to arise from an immune-mediated mechanism (donor antibodies against recipient leukocytes) rather than volume overload; the hypertension and cardiac risk factor here favour TACO.', 1),
('f3000000-0000-0000-0000-000000000042', 'B', 'Acute haemolytic transfusion reaction', false, 'Ruled out because a haemolytic reaction would show haemoglobinuria and loin pain, not the specific cardiorespiratory picture (breathlessness, hypertension, pulmonary oedema) described here, which is characteristic of fluid overload.', 2),
('f3000000-0000-0000-0000-000000000042', 'C', 'Transfusion-associated circulatory overload', true, 'Correct. Acute breathlessness, hypertension and pulmonary oedema developing during or shortly after transfusion, particularly in a patient with pre-existing cardiac impairment, is characteristic of transfusion-associated circulatory overload, caused by rapid volume expansion exceeding cardiac reserve; management includes stopping/slowing the transfusion and diuretic therapy.', 3),
('f3000000-0000-0000-0000-000000000042', 'D', 'Anaphylaxis', false, 'Ruled out because anaphylaxis typically causes hypotension, urticaria and angioedema, not the hypertensive pulmonary oedema picture described, which is specific to volume overload.', 4),
('f3000000-0000-0000-0000-000000000042', 'E', 'Bacterial contamination of the blood product', false, 'Ruled out because bacterial contamination typically causes fever, rigors and septic shock (hypotension), not the specific hypertensive pulmonary oedema picture described here.', 5),
('f3000000-0000-0000-0000-000000000043', 'A', 'Transfusion-associated circulatory overload', false, 'Ruled out because TACO is specifically associated with fluid overload and typically hypertension, not the hypotension and absence of fluid overload/cardiac dysfunction described here, which are more consistent with TRALI.', 1),
('f3000000-0000-0000-0000-000000000043', 'B', 'Anaphylaxis', false, 'Ruled out because anaphylaxis typically presents with urticaria, angioedema and bronchospasm as prominent features, alongside hypotension, not primarily the bilateral pulmonary infiltrate pattern described here.', 2),
('f3000000-0000-0000-0000-000000000043', 'C', 'Acute haemolytic transfusion reaction', false, 'Ruled out because a haemolytic reaction would show haemoglobinuria and loin pain, not the specific acute lung injury pattern described here.', 3),
('f3000000-0000-0000-0000-000000000043', 'D', 'Transfusion-related acute lung injury', true, 'Correct. Acute hypoxia with bilateral pulmonary infiltrates developing within 6 hours of transfusion, with hypotension and no evidence of fluid overload or cardiac dysfunction, is characteristic of transfusion-related acute lung injury, thought to result from donor antibodies reacting against recipient leukocytes, causing non-cardiogenic pulmonary oedema.', 4),
('f3000000-0000-0000-0000-000000000043', 'E', 'Simple pneumonia unrelated to transfusion', false, 'Ruled out because the clear temporal relationship (within hours of transfusion) and absence of an alternative infective explanation point specifically to a transfusion-related lung injury, not coincidental pneumonia.', 5),
('f3000000-0000-0000-0000-000000000044', 'A', 'Anaphylactic transfusion reaction', true, 'Correct. Sudden severe hypotension, bronchospasm and angioedema without fever, in a patient with IgA deficiency, is characteristic of an anaphylactic transfusion reaction, caused by anti-IgA antibodies in the recipient reacting against IgA present in the donor plasma; future transfusions should use IgA-deficient or extensively washed blood products.', 1),
('f3000000-0000-0000-0000-000000000044', 'B', 'Febrile non-haemolytic transfusion reaction', false, 'Ruled out because a febrile non-haemolytic reaction causes fever and chills without the severe anaphylactic features (hypotension, bronchospasm, angioedema) described here.', 2),
('f3000000-0000-0000-0000-000000000044', 'C', 'Acute haemolytic transfusion reaction', false, 'Ruled out because a haemolytic reaction would show haemoglobinuria and loin pain, not the specific anaphylactic features described, and would not be specifically linked to IgA deficiency.', 3),
('f3000000-0000-0000-0000-000000000044', 'D', 'Transfusion-associated circulatory overload', false, 'Ruled out because TACO presents with signs of fluid overload (pulmonary oedema, hypertension), not the anaphylactic features (bronchospasm, angioedema, hypotension without fever) described here.', 4),
('f3000000-0000-0000-0000-000000000044', 'E', 'Bacterial contamination of the blood product', false, $x$Ruled out because bacterial contamination would typically cause fever and signs of sepsis, whereas this reaction occurs without fever and is specifically linked to the patient's known IgA deficiency.$x$, 5),
('f3000000-0000-0000-0000-000000000045', 'A', 'Acute haemolytic transfusion reaction', false, 'Ruled out because a haemolytic reaction would typically cause more severe features including hypotension, loin pain and haemoglobinuria, none of which are present in this milder presentation.', 1),
('f3000000-0000-0000-0000-000000000045', 'B', 'Transfusion-related acute lung injury', false, 'Ruled out because TRALI causes acute hypoxia and respiratory distress, not this mild febrile reaction without respiratory compromise.', 2),
('f3000000-0000-0000-0000-000000000045', 'C', 'Anaphylactic transfusion reaction', false, 'Ruled out because anaphylaxis causes severe hypotension, bronchospasm and angioedema, a much more severe picture than the mild fever and chills described here.', 3),
('f3000000-0000-0000-0000-000000000045', 'D', 'Bacterial contamination of the blood product', false, 'Ruled out because bacterial contamination typically causes a more severe septic picture with marked fever, rigors and haemodynamic instability, not this comparatively mild, isolated fever and chills.', 4),
('f3000000-0000-0000-0000-000000000045', 'E', 'Febrile non-haemolytic transfusion reaction', true, 'Correct. Mild fever and chills during transfusion, without hypotension, respiratory compromise or haemoglobinuria, is the most common and generally benign type of transfusion reaction, caused by recipient antibodies reacting against donor leukocytes or cytokines released during storage; management involves slowing or temporarily stopping the transfusion and giving antipyretics, after excluding more serious reactions.', 5),
('f3000000-0000-0000-0000-000000000046', 'A', 'AB positive blood', false, $x$Ruled out because AB positive is the 'universal recipient' type for plasma, not the universal donor for red cells; giving AB positive red cells to a patient of unknown blood group risks a severe haemolytic reaction if they are not actually AB positive themselves.$x$, 1),
('f3000000-0000-0000-0000-000000000046', 'B', 'Any available blood type, as ABO compatibility is not critical in emergencies', false, 'Ruled out because ABO compatibility remains critical even in emergencies; giving incompatible blood risks a severe, potentially fatal acute haemolytic transfusion reaction.', 2),
('f3000000-0000-0000-0000-000000000046', 'C', 'O negative blood', true, $x$Correct. In a life-threatening emergency where the patient's blood group is unknown and there is no time for crossmatching, O negative red cells (the 'universal donor' type, lacking A, B and RhD antigens) are used to minimise the risk of an acute haemolytic transfusion reaction while full typing and crossmatching are arranged.$x$, 3),
('f3000000-0000-0000-0000-000000000046', 'D', $x$O positive blood only, regardless of the patient's sex or age$x$, false, 'Ruled out because although O positive can sometimes be used in male patients or postmenopausal women in resource-limited emergency settings, O negative is preferred as the safest universal option, particularly relevant in women of childbearing potential due to RhD sensitisation risk.', 4),
('f3000000-0000-0000-0000-000000000046', 'E', 'Waiting for full crossmatch before any transfusion, regardless of clinical urgency', false, $x$Ruled out because in a genuinely life-threatening emergency, waiting for full crossmatching can result in the patient's death from exsanguination; emergency O negative blood is used to bridge this gap.$x$, 5),
('f3000000-0000-0000-0000-000000000047', 'A', 'Anti-D immunoglobulin given to the baby', false, 'Ruled out because anti-D prophylaxis is given to the RhD-negative mother, not the baby; its purpose is to prevent maternal sensitisation against RhD-positive fetal cells, protecting future pregnancies.', 1),
('f3000000-0000-0000-0000-000000000047', 'B', 'Anti-D immunoglobulin given to the mother postnatally', true, 'Correct. Anti-D immunoglobulin given to an RhD-negative mother after delivery of an RhD-positive baby (and at other sensitising events during pregnancy) prevents maternal sensitisation by clearing fetal RhD-positive cells from the maternal circulation before they can trigger an antibody response, protecting future pregnancies from haemolytic disease of the newborn.', 2),
('f3000000-0000-0000-0000-000000000047', 'C', 'No specific treatment needed as this baby is unaffected', false, 'Ruled out because although this baby may be unaffected, anti-D prophylaxis is still needed to prevent maternal sensitisation, which would put future RhD-positive pregnancies at risk of haemolytic disease of the newborn if not given.', 3),
('f3000000-0000-0000-0000-000000000047', 'D', 'Exchange transfusion for the mother', false, 'Ruled out because exchange transfusion is a treatment for severely affected babies with haemolytic disease of the newborn, not a preventive measure given to an unsensitised mother.', 4),
('f3000000-0000-0000-0000-000000000047', 'E', 'Oral iron supplementation for the baby', false, 'Ruled out because this does not address the underlying issue of preventing maternal RhD sensitisation, which is the relevant management point in this scenario.', 5),
('f3000000-0000-0000-0000-000000000048', 'A', 'No prophylaxis needed until after delivery', false, 'Ruled out because routine antenatal prophylaxis (in addition to postnatal prophylaxis if the baby is confirmed RhD-positive) is recommended, as sensitisation can occur from silent fetomaternal haemorrhage during pregnancy itself, not only at delivery.', 1),
('f3000000-0000-0000-0000-000000000048', 'B', 'Anti-D prophylaxis only if a specific sensitising event (e.g. bleeding) occurs', false, 'Ruled out because routine antenatal prophylaxis is given regardless of whether a recognised sensitising event occurs, precisely because many small fetomaternal haemorrhages go clinically undetected.', 2),
('f3000000-0000-0000-0000-000000000048', 'C', 'Immediate exchange transfusion for the mother', false, 'Ruled out because exchange transfusion is not part of routine RhD-negative pregnancy management; anti-D prophylaxis is the appropriate preventive measure.', 3),
('f3000000-0000-0000-0000-000000000048', 'D', 'Routine antenatal anti-D immunoglobulin prophylaxis', true, 'Correct. RhD-negative, unsensitised pregnant women with a potentially RhD-positive fetus are offered routine antenatal anti-D prophylaxis (commonly at 28 weeks, with some regimens including an additional earlier dose), reducing the risk of sensitisation from small, undetected fetomaternal haemorrhages that can occur even without a recognised sensitising event.', 4),
('f3000000-0000-0000-0000-000000000048', 'E', 'Testing and treating the father instead of the mother', false, 'Ruled out because anti-D prophylaxis is specifically given to the RhD-negative mother to prevent her sensitisation; there is no equivalent treatment given to the father in this context.', 5),
('f3000000-0000-0000-0000-000000000049', 'A', 'Transfusional iron overload (secondary haemochromatosis)', true, $x$Correct. Repeated blood transfusions over years, without a corresponding mechanism for iron excretion, leads to progressive iron accumulation in tissues (liver, pancreas, skin, heart), causing skin bronzing, diabetes ('bronze diabetes') and markedly raised ferritin; iron chelation therapy is used to reduce the risk of organ damage in chronically transfused patients.$x$, 1),
('f3000000-0000-0000-0000-000000000049', 'B', 'Primary (hereditary) haemochromatosis', false, 'Ruled out because although the clinical picture overlaps, the clear history of repeated transfusion provides an acquired (secondary) cause for the iron overload, distinguishing it from primary genetic haemochromatosis.', 2),
('f3000000-0000-0000-0000-000000000049', 'C', 'Simple type 2 diabetes unrelated to transfusion history', false, 'Ruled out because the combination of skin bronzing, markedly raised ferritin and new diabetes in a chronically transfused patient points specifically to iron overload as the unifying cause, not coincidental unrelated diabetes.', 3),
('f3000000-0000-0000-0000-000000000049', 'D', 'Acute haemolytic transfusion reaction', false, 'Ruled out because this describes a chronic, progressive process developing over years of transfusion, not an acute reaction occurring during or shortly after a single transfusion.', 4),
('f3000000-0000-0000-0000-000000000049', 'E', $x$Wilson's disease$x$, false, $x$Ruled out because Wilson's disease is a disorder of copper (not iron) metabolism, and would not be explained by a history of chronic transfusion; the specific findings and history point to iron overload instead.$x$, 5),
('f3000000-0000-0000-0000-000000000050', 'A', 'No transfusion is needed as he has no active bleeding', false, 'Ruled out because at very low platelet counts, prophylactic transfusion is used to reduce the risk of spontaneous bleeding (e.g. intracranial haemorrhage) even in the absence of current bleeding, and a higher threshold applies specifically before invasive procedures.', 1),
('f3000000-0000-0000-0000-000000000050', 'B', 'Platelet transfusion should be withheld until the platelet count falls to zero', false, 'Ruled out because waiting for a count of zero would unnecessarily delay appropriate prophylactic treatment; established thresholds guide earlier, appropriately timed transfusion.', 2),
('f3000000-0000-0000-0000-000000000050', 'C', 'Fresh frozen plasma should be given instead of platelets', false, 'Ruled out because FFP replaces clotting factors, not platelets; it is not an appropriate substitute for platelet transfusion in isolated thrombocytopenia.', 3),
('f3000000-0000-0000-0000-000000000050', 'D', 'Red cell transfusion should be given to correct the low platelet count', false, 'Ruled out because red cell transfusion addresses anaemia, not thrombocytopenia; it has no effect on platelet count and is not the appropriate treatment here.', 4),
('f3000000-0000-0000-0000-000000000050', 'E', 'Prophylactic platelet transfusion is indicated given the very low count and planned invasive procedure', true, 'Correct. Prophylactic platelet transfusion is generally indicated at very low platelet counts (commonly below a threshold such as 10x10^9/L) even without active bleeding, to reduce spontaneous bleeding risk, and specific higher thresholds are used before invasive procedures such as lumbar puncture to reduce procedural bleeding risk.', 5)
insert into question_discriminators (question_id, discriminator_text, sort_order) values
('f3000000-0000-0000-0000-000000000001', 'A low ferritin is the most specific and sensitive marker of true iron deficiency, distinguishing it from anaemia of chronic disease, where ferritin is typically normal or raised.', 1),
('f3000000-0000-0000-0000-000000000001', 'A clear source of chronic blood loss (here, menorrhagia) provides the underlying explanation for the iron deficiency, and its identification and management is an important part of treatment.', 2),
('f3000000-0000-0000-0000-000000000001', 'Microcytosis (low MCV) reflects impaired haemoglobin synthesis from inadequate iron availability, a key red cell index supporting the diagnosis.', 3),
('f3000000-0000-0000-0000-000000000002', 'Iron deficiency anaemia in an adult man or postmenopausal woman without an obvious source is considered to be due to gastrointestinal blood loss until proven otherwise, given the risk of underlying malignancy.', 1),
('f3000000-0000-0000-0000-000000000002', 'Bidirectional endoscopy allows assessment of both upper and lower GI tract sources, as either can present with iron deficiency anaemia alone without other symptoms.', 2),
('f3000000-0000-0000-0000-000000000002', 'Prompt investigation is important because colorectal and gastric cancers can present with iron deficiency anaemia as their only initial finding, before other symptoms develop.', 3),
('f3000000-0000-0000-0000-000000000003', 'Hypersegmented neutrophils on blood film reflect impaired DNA synthesis affecting all rapidly dividing cell lines, a classic finding in both B12 and folate deficiency.', 1),
('f3000000-0000-0000-0000-000000000003', 'Neurological symptoms (peripheral neuropathy, subacute combined degeneration of the cord) are specific to B12 deficiency and do not occur with isolated folate deficiency, an important distinguishing clinical feature.', 2),
('f3000000-0000-0000-0000-000000000003', 'A vegan diet, lacking animal products (the main dietary source of B12), is a recognised risk factor for B12 deficiency, particularly without adequate supplementation.', 3),
('f3000000-0000-0000-0000-000000000004', 'Intrinsic factor antibodies are relatively specific for pernicious anaemia, reflecting autoimmune impairment of the intrinsic factor-B12 complex required for terminal ileal absorption.', 1),
('f3000000-0000-0000-0000-000000000004', 'Atrophic gastritis reflects autoimmune destruction of gastric parietal cells, which normally produce both intrinsic factor and gastric acid, and is part of the same underlying autoimmune process.', 2),
('f3000000-0000-0000-0000-000000000004', 'Pernicious anaemia typically requires lifelong parenteral (rather than oral) B12 replacement, since the underlying absorption defect (lack of intrinsic factor) is not corrected by simply increasing oral intake.', 3),
('f3000000-0000-0000-0000-000000000005', 'A markedly low MCV relative to a relatively mild degree of anaemia is characteristic of thalassaemia trait, contrasting with iron deficiency, where the MCV typically falls more proportionately with anaemia severity.', 1),
('f3000000-0000-0000-0000-000000000005', 'Normal ferritin excludes iron deficiency as the cause of microcytosis, an important step before considering haemoglobinopathy.', 2),
('f3000000-0000-0000-0000-000000000005', 'A raised HbA2 level on haemoglobin electrophoresis is the specific diagnostic marker for beta-thalassaemia trait, distinguishing it from alpha-thalassaemia trait.', 3),
('f3000000-0000-0000-0000-000000000006', 'A clear temporal relationship between starting an oxidative drug (sulfonamides, some antimalarials, dapsone) and acute haemolysis is the classic trigger pattern for G6PD deficiency.', 1),
('f3000000-0000-0000-0000-000000000006', 'Bite cells (from splenic removal of Heinz bodies) and Heinz bodies (denatured haemoglobin precipitates) on blood film are specific findings for oxidative haemolysis.', 2),
('f3000000-0000-0000-0000-000000000006', 'G6PD deficiency is X-linked, more commonly affecting males, and is more prevalent in populations from malaria-endemic regions (Africa, the Mediterranean, the Middle East, and parts of Asia), reflecting a degree of protective selection against malaria.', 3),
('f3000000-0000-0000-0000-000000000007', 'Anaemia of chronic disease typically shows normal or raised ferritin (reflecting its role as an acute phase reactant) combined with reduced TIBC/transferrin, distinguishing it from true iron deficiency.', 1),
('f3000000-0000-0000-0000-000000000007', 'Hepcidin, upregulated by chronic inflammation, reduces iron availability for erythropoiesis by limiting intestinal absorption and iron release from macrophage stores, underlying the pathophysiology of this anaemia type.', 2),
('f3000000-0000-0000-0000-000000000007', 'Identifying and treating the underlying chronic condition (here, rheumatoid arthritis) is central to managing anaemia of chronic disease, rather than iron supplementation, which is not the primary treatment when iron stores are already adequate.', 3),
('f3000000-0000-0000-0000-000000000008', 'The kidneys are the principal site of erythropoietin production, so advanced CKD characteristically causes an anaemia driven by relative erythropoietin deficiency.', 1),
('f3000000-0000-0000-0000-000000000008', 'A low reticulocyte count reflects inadequate bone marrow response, consistent with reduced erythropoietin stimulation rather than increased red cell destruction or loss.', 2),
('f3000000-0000-0000-0000-000000000008', 'Excluding other common causes (iron, B12, folate deficiency) is an important step before attributing anaemia to CKD itself, as these can coexist and require separate correction alongside erythropoiesis-stimulating agent therapy if used.', 3),
('f3000000-0000-0000-0000-000000000009', 'The spleen plays a key role in clearing encapsulated bacteria from the bloodstream via opsonisation and phagocytosis, explaining the specific vulnerability to these organisms after splenectomy.', 1),
('f3000000-0000-0000-0000-000000000009', 'Vaccination (against pneumococcus, Haemophilus influenzae type b, and meningococcus) should ideally be given before splenectomy where possible, with booster doses as per local guidelines.', 2),
('f3000000-0000-0000-0000-000000000009', 'Patients should be counselled to seek urgent medical attention for any fever, given the potential for rapid, life-threatening deterioration from overwhelming post-splenectomy infection.', 3),
('f3000000-0000-0000-0000-000000000010', 'A positive direct antiglobulin (Coombs) test confirms that red cells are coated with antibody and/or complement, specifically indicating an immune-mediated haemolytic process.', 1),
('f3000000-0000-0000-0000-000000000010', 'Spherocytes form when antibody-coated red cells are partially phagocytosed by splenic macrophages, losing membrane and becoming spherical, and can occur in both AIHA and hereditary spherocytosis, making the DAT the key discriminating test between them.', 2),
('f3000000-0000-0000-0000-000000000010', 'Raised LDH and reduced haptoglobin (which binds and clears free haemoglobin) together with reticulocytosis are general markers of active haemolysis, regardless of the specific underlying cause.', 3),
('f3000000-0000-0000-0000-000000000011', 'Pancytopenia with circulating blast cells reflects bone marrow infiltration by leukaemic cells crowding out normal haematopoiesis across all cell lines.', 1),
('f3000000-0000-0000-0000-000000000011', 'A bone marrow blast count above 20% is the diagnostic threshold for acute leukaemia, distinguishing it from other marrow disorders.', 2),
('f3000000-0000-0000-0000-000000000011', 'ALL is the most common malignancy of childhood, with a peak incidence in early childhood, distinguishing its epidemiology from AML (more common in adults) and CLL (a disease of older adults).', 3),
('f3000000-0000-0000-0000-000000000012', 'Auer rods are pathognomonic for myeloid blast lineage, providing a specific morphological clue distinguishing AML from ALL, where they are not seen.', 1),
('f3000000-0000-0000-0000-000000000012', 'Bleeding and bruising reflect thrombocytopenia from marrow infiltration, a common presenting feature of acute leukaemia regardless of lineage.', 2),
('f3000000-0000-0000-0000-000000000012', 'AML is more common in adults (with incidence increasing with age), in contrast to ALL, which predominates in children, though both can occur at any age.', 3),
('f3000000-0000-0000-0000-000000000013', 'Acute promyelocytic leukaemia has a particularly strong, well-recognised association with DIC, related to release of procoagulant granule contents from the abnormal promyelocytes.', 1),
('f3000000-0000-0000-0000-000000000013', 'DIC characteristically shows a prolonged PT and APTT together with a low fibrinogen and low platelets, reflecting widespread consumption of clotting factors, distinguishing it from isolated factor deficiencies.', 2),
('f3000000-0000-0000-0000-000000000013', 'Prompt recognition of DIC in APL is clinically important, as this is a medical emergency requiring urgent treatment (including specific APL therapy with ATRA) alongside blood product support.', 3),
('f3000000-0000-0000-0000-000000000014', 'Smudge (smear) cells, formed when fragile CLL lymphocytes rupture during blood film preparation, are a classic and relatively specific morphological finding in chronic lymphocytic leukaemia.', 1),
('f3000000-0000-0000-0000-000000000014', 'CLL often has an indolent course and is frequently diagnosed incidentally on a routine blood test in an asymptomatic patient, in contrast to the acute presentation of ALL.', 2),
('f3000000-0000-0000-0000-000000000014', 'CLL is a disease predominantly of older adults, with lymphocytes that appear mature (small, with condensed chromatin), distinguishing it morphologically from the immature blast cells of acute leukaemias.', 3),
('f3000000-0000-0000-0000-000000000015', 'The Philadelphia chromosome (BCR-ABL1 fusion from t(9;22)) is the defining genetic abnormality of CML, present in the vast majority of cases and directly targetable by tyrosine kinase inhibitor therapy.', 1),
('f3000000-0000-0000-0000-000000000015', 'A chronic leucocytosis with a full spectrum of maturing granulocytes (rather than blast predominance) reflects the chronic phase of CML, distinguishing it from the blast-predominant picture of acute leukaemia.', 2),
('f3000000-0000-0000-0000-000000000015', 'Massive splenomegaly reflects extramedullary haematopoiesis and leukaemic cell infiltration, often a prominent presenting feature in CML.', 3),
('f3000000-0000-0000-0000-000000000016', 'Reed-Sternberg cells are the pathognomonic histological finding required to diagnose Hodgkin lymphoma, distinguishing it definitively from non-Hodgkin lymphoma and other causes of lymphadenopathy.', 1),
('f3000000-0000-0000-0000-000000000016', $x$'B symptoms' (fever, drenching night sweats, weight loss exceeding 10% of body weight over 6 months) are systemic features used both diagnostically and for staging/prognostic purposes in lymphoma.$x$, 2),
('f3000000-0000-0000-0000-000000000016', 'Hodgkin lymphoma has a bimodal age distribution, with peaks in young adults and again in older age, and carries a generally favourable prognosis with modern treatment compared with many other haematological malignancies.', 3),
('f3000000-0000-0000-0000-000000000017', 'Absence of Reed-Sternberg cells on lymph node biopsy, in the context of a lymphoid malignancy, distinguishes non-Hodgkin lymphoma from Hodgkin lymphoma.', 1),
('f3000000-0000-0000-0000-000000000017', 'Rapid progression over weeks, multi-site involvement and systemic symptoms are typical of aggressive (high-grade) non-Hodgkin lymphoma subtypes such as diffuse large B-cell lymphoma.', 2),
('f3000000-0000-0000-0000-000000000017', 'Non-Hodgkin lymphoma encompasses a heterogeneous group of B-cell and T-cell malignancies with varying aggressiveness, in contrast to the more uniform biology of Hodgkin lymphoma.', 3),
('f3000000-0000-0000-0000-000000000018', 'Rapid cell death from chemotherapy in a bulky, rapidly proliferating tumour releases large amounts of intracellular potassium, phosphate and nucleic acids (metabolised to uric acid), overwhelming normal renal clearance.', 1),
('f3000000-0000-0000-0000-000000000018', $x$Hypocalcaemia occurs because the released phosphate binds calcium, precipitating as calcium phosphate, distinguishing tumour lysis syndrome's electrolyte pattern from other causes of AKI.$x$, 2),
('f3000000-0000-0000-0000-000000000018', 'High-risk patients (bulky, rapidly proliferating tumours such as high-grade lymphoma or leukaemia) receive prophylactic measures (hydration, allopurinol or rasburicase) before starting chemotherapy specifically to reduce this risk.', 3),
('f3000000-0000-0000-0000-000000000019', 'Imatinib represents a landmark example of targeted molecular therapy, specifically inhibiting the abnormal fusion protein driving the malignancy, rather than acting as a broad cytotoxic agent.', 1),
('f3000000-0000-0000-0000-000000000019', $x$This targeted mechanism explains imatinib's relatively favourable side-effect profile compared with traditional cytotoxic chemotherapy, as it largely spares cells not expressing the BCR-ABL1 fusion protein.$x$, 2),
('f3000000-0000-0000-0000-000000000019', 'The dramatic efficacy of tyrosine kinase inhibitors has transformed CML from a once rapidly fatal disease into a chronic, manageable condition for most patients.', 3),
('f3000000-0000-0000-0000-000000000020', 'CLL frequently impairs normal humoral immunity, even when the malignant lymphocyte count itself may not be dramatically elevated, reflecting qualitative rather than purely quantitative immune dysfunction.', 1),
('f3000000-0000-0000-0000-000000000020', 'Recurrent bacterial infections (particularly respiratory and sinus infections) are a common and clinically significant complication of CLL-associated hypogammaglobulinaemia.', 2),
('f3000000-0000-0000-0000-000000000020', 'Immunoglobulin replacement therapy is considered in patients with CLL who have recurrent, significant infections associated with confirmed hypogammaglobulinaemia, aiming to reduce infection frequency and severity.', 3),
('f3000000-0000-0000-0000-000000000021', 'An isolated prolonged APTT with a normal PT localises the defect to the intrinsic coagulation pathway, narrowing the differential to factors VIII, IX, XI or XII deficiency, or an inhibitor.', 1),
('f3000000-0000-0000-0000-000000000021', 'Recurrent haemarthroses (bleeding into joints) are a classic and distinguishing feature of haemophilia, reflecting the severity and pattern of bleeding compared with platelet-type bleeding disorders.', 2),
('f3000000-0000-0000-0000-000000000021', 'X-linked recessive inheritance explains why haemophilia A predominantly affects males, an important epidemiological clue supporting the diagnosis.', 3),
('f3000000-0000-0000-0000-000000000022', 'Mucocutaneous bleeding (menorrhagia, epistaxis, easy bruising, prolonged bleeding after dental work) is the characteristic bleeding pattern of von Willebrand disease, distinguishing it from the deep joint/muscle bleeding typical of haemophilia.', 1),
('f3000000-0000-0000-0000-000000000022', 'Von Willebrand factor stabilises factor VIII in plasma, so reduced vWF can secondarily cause a mildly prolonged APTT via reduced factor VIII levels.', 2),
('f3000000-0000-0000-0000-000000000022', 'Von Willebrand disease is the most common inherited bleeding disorder and, unlike haemophilia, typically affects males and females equally, as it is usually inherited in an autosomal pattern.', 3),
('f3000000-0000-0000-0000-000000000023', 'Simultaneous bleeding and thrombosis is a hallmark clinical feature of DIC, reflecting widespread, dysregulated activation of both coagulation and fibrinolysis.', 1),
('f3000000-0000-0000-0000-000000000023', 'The combination of prolonged PT and APTT, low fibrinogen, thrombocytopenia and raised D-dimer together (rather than any single abnormality) supports a diagnosis of DIC.', 2),
('f3000000-0000-0000-0000-000000000023', 'Sepsis is one of the most common triggers of DIC, alongside other conditions such as major trauma, obstetric emergencies and certain malignancies (particularly acute promyelocytic leukaemia).', 3),
('f3000000-0000-0000-0000-000000000024', 'Isolated thrombocytopenia with otherwise normal coagulation studies (PT, APTT, fibrinogen) points to a primary platelet disorder rather than a global coagulopathy.', 1),
('f3000000-0000-0000-0000-000000000024', 'A preceding viral infection is a recognised trigger for ITP, particularly in children and young adults, reflecting an immune-mediated cross-reactive process against platelets.', 2),
('f3000000-0000-0000-0000-000000000024', 'Absence of splenomegaly is typical in ITP (platelets are destroyed by antibody-mediated clearance, predominantly in the spleen, but without causing splenic enlargement), distinguishing it from conditions causing thrombocytopenia via splenic sequestration.', 3),
('f3000000-0000-0000-0000-000000000025', 'Schistocytes on blood film reflect mechanical red cell fragmentation as cells pass through platelet-rich microthrombi in small vessels, defining a microangiopathic haemolytic process.', 1),
('f3000000-0000-0000-0000-000000000025', 'Normal coagulation studies (PT, APTT, fibrinogen) distinguish TTP from DIC, despite both causing thrombocytopenia and organ dysfunction, an important and frequently tested discriminator.', 2),
('f3000000-0000-0000-0000-000000000025', 'Severe ADAMTS13 deficiency (an enzyme that normally cleaves large von Willebrand factor multimers) underlies TTP, leading to platelet microthrombi formation; urgent plasma exchange remains the mainstay emergency treatment.', 3),
('f3000000-0000-0000-0000-000000000026', 'Prothrombin complex concentrate provides immediate replacement of the vitamin K-dependent clotting factors (II, VII, IX, X) depleted by warfarin, correcting the coagulopathy far more rapidly than vitamin K alone.', 1),
('f3000000-0000-0000-0000-000000000026', 'IV (rather than oral) vitamin K is used in this emergency setting for a faster onset of action, working alongside PCC to sustain factor correction as the PCC effect wanes.', 2),
('f3000000-0000-0000-0000-000000000026', 'Major or life-threatening bleeding on warfarin requires this combined, rapid reversal approach, in contrast to management of a minor elevated INR without bleeding, which may simply involve withholding doses or lower-intensity intervention.', 3),
('f3000000-0000-0000-0000-000000000027', 'Understanding that warfarin inhibits vitamin K epoxide reductase (preventing vitamin K recycling) explains why administering vitamin K can overcome this blockade and restore normal factor synthesis over time.', 1),
('f3000000-0000-0000-0000-000000000027', 'The carboxylation modification vitamin K enables allows clotting factors to bind calcium ions, which is essential for their participation in the coagulation cascade on phospholipid surfaces.', 2),
('f3000000-0000-0000-0000-000000000027', 'Because this synthesis pathway takes time (new functional factors must be produced), vitamin K alone acts more slowly than PCC, which is why both are combined for rapid reversal in emergency bleeding.', 3),
('f3000000-0000-0000-0000-000000000028', 'A mixing study distinguishes a factor deficiency (which corrects when normal plasma is added, supplying the missing factor) from an inhibitor (which does not correct, as it continues to interfere with the added normal factors too).', 1),
('f3000000-0000-0000-0000-000000000028', 'Lupus anticoagulant is a laboratory paradox: it prolongs clotting times in vitro (interfering with phospholipid-dependent test reagents) while being associated with an increased thrombotic (not bleeding) risk in vivo.', 2),
('f3000000-0000-0000-0000-000000000028', 'The clinical history of recurrent miscarriage and unprovoked thrombosis strongly supports antiphospholipid syndrome, of which lupus anticoagulant is one of the defining laboratory criteria (alongside anticardiolipin and anti-beta2-glycoprotein I antibodies).', 3),
('f3000000-0000-0000-0000-000000000029', 'The lack of need for routine coagulation monitoring is a major practical advantage of DOACs over warfarin, reflecting their more predictable pharmacokinetics and pharmacodynamics.', 1),
('f3000000-0000-0000-0000-000000000029', 'Periodic renal function monitoring remains important for DOACs, as several (including rivaroxaban) are partially renally cleared, and dose adjustment or caution may be needed in renal impairment.', 2),
('f3000000-0000-0000-0000-000000000029', 'In specific situations (e.g. suspected overdose, need for reversal before emergency surgery, or assessing compliance), specific DOAC-calibrated assays exist, but these are not part of routine monitoring in stable patients.', 3),
('f3000000-0000-0000-0000-000000000030', 'A characteristic fall in platelet count typically occurring 5-10 days after starting heparin (or more rapidly with prior heparin exposure) is the classic temporal pattern for HIT.', 1),
('f3000000-0000-0000-0000-000000000030', 'Paradoxical new thrombosis, despite falling platelets, is a distinguishing and clinically critical feature of HIT, differentiating it from other causes of drug-induced thrombocytopenia that are primarily associated with bleeding risk.', 2),
('f3000000-0000-0000-0000-000000000030', 'Heparin must be stopped immediately on suspicion of HIT, with a non-heparin anticoagulant (e.g. a direct thrombin inhibitor) substituted, given the high risk of severe thrombotic complications if heparin is continued.', 3),
('f3000000-0000-0000-0000-000000000031', 'The JAK2 V617F mutation is present in the large majority of polycythaemia vera cases, providing a key diagnostic marker distinguishing it from secondary or relative polycythaemia.', 1),
('f3000000-0000-0000-0000-000000000031', 'Aquagenic pruritus (itching triggered by warm water exposure) is a classically described, relatively specific symptom of polycythaemia vera.', 2),
('f3000000-0000-0000-0000-000000000031', 'Distinguishing primary (clonal, JAK2-positive) from secondary (EPO-driven) polycythaemia is essential, as management and associated risks (thrombosis in PV) differ significantly.', 3),
('f3000000-0000-0000-0000-000000000032', 'Increased red cell mass raises blood viscosity, directly increasing the risk of both arterial and venous thrombotic events, the leading cause of morbidity and mortality in PV.', 1),
('f3000000-0000-0000-0000-000000000032', 'Venesection to maintain haematocrit below a target threshold (commonly below 0.45) is a cornerstone of reducing thrombotic risk in PV.', 2),
('f3000000-0000-0000-0000-000000000032', 'Low-dose aspirin is typically also used to further reduce thrombotic risk, alongside cytoreductive therapy (e.g. hydroxycarbamide) in patients at higher risk (e.g. older age, prior thrombosis).', 3),
('f3000000-0000-0000-0000-000000000033', 'Excluding secondary (reactive) causes of thrombocytosis is an essential step before diagnosing a primary myeloproliferative neoplasm such as essential thrombocythaemia.', 1),
('f3000000-0000-0000-0000-000000000033', 'JAK2 V617F (or other driver mutations such as CALR or MPL) supports a clonal, primary process, distinguishing ET from reactive thrombocytosis.', 2),
('f3000000-0000-0000-0000-000000000033', 'Essential thrombocythaemia carries an increased risk of both thrombosis and, at very high platelet counts, paradoxical bleeding (from acquired von Willebrand syndrome), informing management decisions around cytoreductive therapy.', 3),
('f3000000-0000-0000-0000-000000000034', 'Teardrop-shaped red cells (dacrocytes) on blood film are a classic finding in myelofibrosis, reflecting mechanical deformation as red cells are extruded through the fibrotic marrow.', 1),
('f3000000-0000-0000-0000-000000000034', $x$A 'dry tap' on bone marrow aspiration (inability to aspirate marrow due to extensive fibrosis) necessitates trephine biopsy to confirm the diagnosis histologically.$x$, 2),
('f3000000-0000-0000-0000-000000000034', 'Massive splenomegaly reflects extramedullary haematopoiesis compensating for the failing, fibrotic bone marrow, often the most prominent clinical finding in myelofibrosis.', 3),
('f3000000-0000-0000-0000-000000000035', 'Maintaining haematocrit below a defined target (commonly below 0.45) through regular venesection has been shown to significantly reduce cardiovascular events in polycythaemia vera.', 1),
('f3000000-0000-0000-0000-000000000035', 'Venesection addresses the haematocrit/viscosity-related thrombotic risk specifically, while other therapies (aspirin, cytoreductive agents) address complementary aspects of overall risk reduction.', 2),
('f3000000-0000-0000-0000-000000000035', 'Venesection is a risk-reduction and symptom-control measure, not a disease-modifying or curative treatment for the underlying JAK2-driven clonal process.', 3),
('f3000000-0000-0000-0000-000000000036', 'A recognised long-term complication of polycythaemia vera (and essential thrombocythaemia) is transformation to secondary myelofibrosis, sharing the same underlying clonal myeloproliferative process.', 1),
('f3000000-0000-0000-0000-000000000036', 'The shift from erythrocytosis to worsening anaemia reflects progressive marrow failure as fibrosis develops, despite the same underlying disease process.', 2),
('f3000000-0000-0000-0000-000000000036', 'Recognising this transformation is important, as management shifts from venesection-based haematocrit control towards management of myelofibrosis, including consideration of JAK inhibitor therapy or, in eligible patients, allogeneic stem cell transplantation.', 3),
('f3000000-0000-0000-0000-000000000037', 'This paradoxical bleeding risk at very high platelet counts (rather than the thrombotic risk typically associated with thrombocytosis) is an important, counterintuitive clinical point in essential thrombocythaemia management.', 1),
('f3000000-0000-0000-0000-000000000037', 'The mechanism involves excessive platelet-mediated removal of large von Willebrand factor multimers from plasma, functionally mimicking von Willebrand disease.', 2),
('f3000000-0000-0000-0000-000000000037', 'Recognising this risk is clinically important, as it may influence decisions about cytoreductive therapy to lower the platelet count and reduce bleeding risk, alongside avoiding antiplatelet agents that could further increase bleeding tendency at very high platelet counts.', 3),
('f3000000-0000-0000-0000-000000000038', 'Cytoreductive therapy is reserved for higher-risk patients (typically age over 60 or with a prior thrombotic event) in polycythaemia vera, reflecting a risk-stratified treatment approach.', 1),
('f3000000-0000-0000-0000-000000000038', 'Hydroxycarbamide reduces production across multiple blood cell lines, addressing the underlying clonal overproduction rather than just removing existing excess cells (as venesection does for red cells alone).', 2),
('f3000000-0000-0000-0000-000000000038', 'Combining cytoreductive therapy with venesection and low-dose aspirin provides a multi-pronged approach to reducing the significant thrombotic risk in higher-risk PV patients.', 3),
('f3000000-0000-0000-0000-000000000039', 'Hepatic vein thrombosis (Budd-Chiari syndrome) at this atypical venous site should always prompt consideration of an underlying prothrombotic condition, with myeloproliferative neoplasms being a leading cause.', 1),
('f3000000-0000-0000-0000-000000000039', 'Myeloproliferative neoplasms can predispose to thrombosis at unusual sites (hepatic, portal, splenic, cerebral venous sinuses) even when peripheral blood counts appear only mildly elevated or are masked by haemoconcentration/dilution effects.', 2),
('f3000000-0000-0000-0000-000000000039', 'JAK2 V617F mutation testing (and, if negative, further specific myeloproliferative neoplasm workup) is an important part of investigating unexplained or atypical-site venous thrombosis.', 3),
('f3000000-0000-0000-0000-000000000040', 'Risk stratification in ET (based on age, prior thrombosis, and other factors) determines whether cytoreductive therapy is added to low-dose aspirin, reflecting a risk-adapted treatment approach.', 1),
('f3000000-0000-0000-0000-000000000040', 'Low-dose aspirin reduces platelet aggregation and thrombotic risk, forming the foundation of ET management even in lower-risk patients.', 2),
('f3000000-0000-0000-0000-000000000040', 'Cytoreductive agents (e.g. hydroxycarbamide) are reserved for higher-risk patients to reduce platelet production itself, going beyond the antiplatelet effect of aspirin alone.', 3),
('f3000000-0000-0000-0000-000000000041', 'Rapid onset (within minutes) of fever, loin pain and hypotension during a transfusion is a red-flag pattern for acute haemolytic transfusion reaction, requiring immediate cessation of the transfusion.', 1),
('f3000000-0000-0000-0000-000000000041', 'Haemoglobinuria (dark urine) reflects intravascular haemolysis and free haemoglobin being filtered by the kidneys, a specific and serious finding distinguishing this from milder transfusion reactions.', 2),
('f3000000-0000-0000-0000-000000000041', 'ABO incompatibility, usually from a clerical/identification error, is the most common and most dangerous cause of acute haemolytic transfusion reactions, underscoring the importance of rigorous patient identification checks before and during transfusion.', 3),
('f3000000-0000-0000-0000-000000000042', 'Hypertension (rather than hypotension) alongside pulmonary oedema is a key distinguishing feature of TACO from TRALI, which are otherwise similar in presenting with acute respiratory compromise.', 1),
('f3000000-0000-0000-0000-000000000042', 'Pre-existing cardiac or renal impairment increases the risk of TACO, as these patients have reduced capacity to accommodate rapid volume expansion.', 2),
('f3000000-0000-0000-0000-000000000042', 'Slower transfusion rates and, where appropriate, diuretic cover can help prevent and manage TACO in patients at higher risk, such as those with known heart failure.', 3),
('f3000000-0000-0000-0000-000000000043', 'TRALI is defined by acute lung injury (hypoxia, bilateral infiltrates) occurring within 6 hours of transfusion, in the absence of another cause and without evidence of fluid overload.', 1),
('f3000000-0000-0000-0000-000000000043', 'Unlike TACO, TRALI is typically associated with hypotension rather than hypertension, and reflects a non-cardiogenic mechanism (increased pulmonary capillary permeability) rather than volume overload.', 2),
('f3000000-0000-0000-0000-000000000043', 'The proposed mechanism involves donor plasma containing antibodies against recipient neutrophil or HLA antigens, triggering neutrophil activation and capillary leak within the lungs.', 3),
('f3000000-0000-0000-0000-000000000044', 'IgA deficiency is a specific, recognised risk factor for severe anaphylactic transfusion reactions, as affected individuals can develop anti-IgA antibodies that react against IgA in donor plasma.', 1),
('f3000000-0000-0000-0000-000000000044', 'Absence of fever, combined with severe hypotension, bronchospasm and angioedema, distinguishes an anaphylactic reaction from the more common febrile non-haemolytic transfusion reaction.', 2),
('f3000000-0000-0000-0000-000000000044', 'Patients with a history of this reaction require specific future precautions, such as washed red cells or IgA-deficient blood products, to prevent recurrence.', 3),
('f3000000-0000-0000-0000-000000000045', 'Febrile non-haemolytic transfusion reactions are the most common transfusion reaction and are generally mild and self-limiting, distinguishing them from the more serious reactions requiring urgent intervention.', 1),
('f3000000-0000-0000-0000-000000000045', 'The absence of hypotension, respiratory compromise or haemoglobinuria helps exclude the more serious differential diagnoses (haemolytic reaction, TRALI, anaphylaxis, bacterial contamination).', 2),
('f3000000-0000-0000-0000-000000000045', 'Even with a presumed febrile non-haemolytic reaction, the transfusion is typically paused and the patient reassessed to ensure a more serious reaction is not evolving, given overlapping early symptoms.', 3),
('f3000000-0000-0000-0000-000000000046', 'O negative red cells lack the major ABO and RhD antigens, making them compatible (in terms of avoiding acute haemolysis) with recipients of any blood group in a genuine emergency.', 1),
('f3000000-0000-0000-0000-000000000046', 'RhD status is particularly important in women of childbearing potential, as RhD-positive blood given to an RhD-negative woman risks sensitisation, which could affect future pregnancies; O negative avoids this risk.', 2),
('f3000000-0000-0000-0000-000000000046', 'Emergency O negative transfusion is a temporary bridging measure while formal blood typing and crossmatching are urgently arranged, after which type-specific or fully crossmatched blood is used as soon as possible.', 3),
('f3000000-0000-0000-0000-000000000047', 'Anti-D immunoglobulin works by clearing fetal RhD-positive red cells from the maternal circulation before the maternal immune system can mount a sensitising antibody response.', 1),
('f3000000-0000-0000-0000-000000000047', 'Prophylaxis is given at defined times during pregnancy (e.g. routinely in the third trimester) and after any potentially sensitising event (delivery, miscarriage, antepartum haemorrhage, invasive procedures), not just after birth.', 2),
('f3000000-0000-0000-0000-000000000047', 'Preventing maternal sensitisation in this pregnancy is specifically important for protecting future pregnancies, as it is subsequent (not the current) RhD-positive pregnancies that are at risk of haemolytic disease of the newborn once sensitisation has occurred.', 3),
('f3000000-0000-0000-0000-000000000048', 'Routine antenatal anti-D prophylaxis addresses the risk of sensitisation from asymptomatic, undetected fetomaternal haemorrhage occurring spontaneously during pregnancy, not just at recognised sensitising events.', 1),
('f3000000-0000-0000-0000-000000000048', 'This is given in addition to postnatal anti-D if the baby is confirmed RhD-positive after birth, providing protection across the whole pregnancy and delivery period.', 2),
('f3000000-0000-0000-0000-000000000048', 'The goal throughout is prevention of maternal sensitisation, which would otherwise risk haemolytic disease of the newborn in a subsequent RhD-positive pregnancy.', 3),
('f3000000-0000-0000-0000-000000000049', 'The body has no active mechanism for excreting excess iron, meaning repeated transfusions (each containing significant iron) progressively lead to iron accumulation in tissues over time.', 1),
('f3000000-0000-0000-0000-000000000049', 'Skin bronzing, diabetes and, in more advanced cases, cardiac and liver dysfunction reflect iron deposition in these specific organs, forming the classic multi-organ picture of iron overload.', 2),
('f3000000-0000-0000-0000-000000000049', 'Regular monitoring of ferritin and iron studies in chronically transfused patients allows timely initiation of iron chelation therapy to prevent or reduce the severity of end-organ damage.', 3),
('f3000000-0000-0000-0000-000000000050', 'Prophylactic platelet transfusion thresholds are used to reduce spontaneous bleeding risk at very low counts, distinguishing this from therapeutic transfusion given in response to active bleeding.', 1),
('f3000000-0000-0000-0000-000000000050', 'Higher platelet count thresholds are applied before specific invasive procedures (such as lumbar puncture or surgery) than for general prophylaxis, reflecting the additional procedural bleeding risk.', 2),
('f3000000-0000-0000-0000-000000000050', 'Platelet transfusion is specific to thrombocytopenia and should not be confused with FFP (for clotting factor deficiency) or red cell transfusion (for anaemia), each addressing a distinct haematological deficit.', 3);
